/* ---- set-aside notice on the login screen (FINDING-003) -----------------
   Rendered only when set-aside data exists, and placed above the login form so
   it is on screen before sign-in. Higher specificity than .wl-login so it wins
   over the runtime-injected login stylesheet regardless of order. */
.wl-login.wl-login-setaside{align-items:flex-start;}
.wl-setaside{margin:0 0 22px;padding:14px;border-radius:14px;
  background:var(--card);border:1px solid var(--accent);}
