.wl-setaside-row{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:10px;}
.wl-setaside-date{flex:1 1 100%;color:var(--muted);font-size:13px;}
.wl-setaside .wl-btn{flex:1 1 0;min-width:120px;min-height:44px;padding:10px 12px;
  font-size:14px;white-space:normal;}
.wl-setaside .wl-btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px;}
@media(max-width:400px){
  .wl-setaside{padding:12px;}
  .wl-setaside .wl-btn{min-width:0;}
