/* ---- Commit 10: the conflict centre ------------------------------------
   Non-modal by design. It sits above the page but never traps focus and
   never blocks an active workout: the athlete reaches it when they choose
   to. Every rule here is sized in relative units so long labels wrap
   instead of truncating — the copy explains what happens to someone's
   data, and a clipped explanation is worse than none. */
.cf-conflict-host{position:fixed;left:0;right:0;bottom:0;z-index:60;
  max-height:min(86vh,720px);overflow-y:auto;-webkit-overflow-scrolling:touch;
  background:var(--bg);border-top:1px solid var(--line);
  box-shadow:0 -12px 40px rgba(0,0,0,.45);
  padding:18px 16px calc(18px + env(safe-area-inset-bottom,0px));}
.cf-conflict-host:empty{display:none;}
.cf-conflict-center{max-width:640px;margin:0 auto;}
/* inline-block so the focus ring hugs the words. As a full-width block the
   heading's ring drew a box across the whole sheet, which reads as a selected
   container rather than as "focus is here". */
.cf-conflict-center h2{display:inline-block;font-size:18px;line-height:1.3;margin:0 0 12px;font-weight:800;}
.cf-conflict-center h2:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:6px;}
.cf-conflict-close{margin-top:6px;min-height:44px;}
.cf-conflict-card{margin:14px 0;padding:15px;}
.cf-conflict-title{font-size:14px;font-weight:800;margin:0 0 10px;letter-spacing:.01em;}
.cf-conflict-title:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:6px;}
.cf-conflict-body{margin:0 0 13px;font-size:14px;line-height:1.5;color:var(--text);}
/* Help text belongs to the action above it, so it hugs that button and keeps
   a clear gap before the next one — the boundary between two destructive
   choices has to stay obvious at a glance. */
.cf-conflict-help{margin:7px 2px 16px;font-size:12.5px;line-height:1.45;color:var(--muted);
  overflow-wrap:anywhere;}
.cf-conflict-note{margin:0 0 12px;padding:9px 11px;border-radius:10px;font-size:13px;line-height:1.45;
  background:var(--accent-dim);border:1px solid rgba(245,181,68,.45);color:var(--text);}
.cf-conflict-note:focus-visible{outline:2px solid var(--accent);outline-offset:2px;}
/* Full-width, left-aligned, generous target. Centre-aligned labels of very
   different lengths read as unrelated; left alignment keeps the three
   choices scannable as one list. */
.cf-conflict-card .wl-btn{justify-content:flex-start;text-align:left;width:100%;
  min-height:46px;padding:12px 14px;line-height:1.35;white-space:normal;overflow-wrap:anywhere;}
.cf-conflict-card .wl-btn:disabled{opacity:.55;filter:grayscale(.3);}
.cf-action-secondary{margin-top:14px;}
.cf-conflict-busy{margin:0;font-size:13px;color:var(--muted);}
/* The focus ring must survive every state, including disabled-adjacent and
   ghost buttons on the card background. */
.cf-conflict-host .wl-btn:focus-visible,.cf-conflict-close:focus-visible{
  outline:2px solid var(--accent);outline-offset:2px;}
/* The header dot's non-colour cue: a shape as well as a hue, so the state is
   legible without colour vision and at a glance. */
.cf-dot-cue{display:inline-flex;align-items:center;justify-content:center;
  min-width:14px;height:14px;margin-left:5px;padding:0 3px;border-radius:7px;
  font-size:10px;font-weight:900;line-height:1;vertical-align:middle;}
.cf-dot-cue-warn{background:var(--accent);color:var(--on-accent);}
.cf-dot-cue-bad{background:var(--bad);color:#fff;}
/* .wl-syncdot is a fixed 22x22 box built for a 7px dot alone. With the cue
