   grows only while it carries one — and reverts when the workflow clears. */
.wl-syncdot[aria-controls]{display:inline-flex;align-items:center;justify-content:center;
  width:auto;min-width:22px;padding:0 3px;gap:3px;}
.cf-status{display:inline-flex;align-items:center;gap:6px;width:auto;height:auto;
