/* ============================================================
   HARDENING — MILESTONE 1: account-scope all photo storage
   ------------------------------------------------------------
   Photos were device-global: IndexedDB records and the local
   photo→server map carried no owner. After a logout the blobs and
   the map both survived, so the NEXT account's first sync saw them
   as "local photos the server doesn't have" and uploaded User A's
   photos into User B's account — and, because the stale map still
   listed them, mirrored a remote deletion back onto this device.
   Every photo now carries an immutable ownerId and may only be
   displayed, uploaded, deleted, reconciled or mapped when that
   ownerId matches the authenticated PocketBase user.
   ============================================================ */

/* @testable-start M1 — pure predicates, no DOM/network (see tests/) */
/* A record belongs to the signed-in account only on an exact match.
   No uid (signed out) owns nothing; an ownerless legacy record is
   owned by NOBODY and must never be inferred onto the current user. */
function phIsMine(rec,uid){return !!(uid&&rec&&rec.ownerId===uid);}
function phIsOrphan(rec){return !!(rec&&!rec.ownerId);}
function phFilterMine(list,uid){return (list||[]).filter(function(r){return phIsMine(r,uid);});}
/* @testable-end M1 */

var PH_ACCT_KEY="wl_lastacct";
function phOwner(){return pbUid()||"";}
function phMapKey(){return PB_PMAP+":"+phOwner();}

/* The photo→server map is per-account. The legacy flat map belonged to
   whichever account last used this device — unknowable now, and trusting it
   drives deletion inference, so it is discarded rather than guessed at.
   Losing it is safe: uploads dedupe on the server's UNIQUE (user, localId)
   index, so the next sync simply re-establishes the mapping. */
pbPhotoMap=function(){var me=phOwner();if(!me)return {};
  try{return JSON.parse(localStorage.getItem(phMapKey()))||{};}catch(e){return {};}};
setPbPhotoMap=function(m){var me=phOwner();if(!me)return;
  try{localStorage.setItem(phMapKey(),JSON.stringify(m||{}));}catch(e){}};
try{if(localStorage.getItem(PB_PMAP)!=null)localStorage.removeItem(PB_PMAP);}catch(e){}

/* raw, unscoped primitives — everything else goes through the scoped ones */
var _phAllRaw=idbAll,_phByDateRaw=idbByDate,_phAddLocal=idbAddLocal,_phDelLocal=idbDeleteLocal;
function phStamp(rec){var me=phOwner();
  if(me&&!rec.ownerId)rec.ownerId=me;
  if(!rec.localId)rec.localId=rec.id;
  if(!rec.createdAt)rec.createdAt=rec.ts||Date.now();
  return rec;}
function phAllAny(){return _phAllRaw();}
function phOrphans(){return _phAllRaw().then(function(a){return (a||[]).filter(phIsOrphan);});}

/* photoSync writes server-sourced records through idbAddLocal (the raw put, so
   they don't bounce straight back up). Stamp there too — an unstamped download
   would land ownerless and be invisible to the very account that just pulled it. */
idbAddLocal=function(rec){return _phAddLocal(phStamp(rec));};

/* every READ path is account-scoped: a photo belonging to another account is
   not merely un-syncable, it is invisible */
idbAll=function(){return _phAllRaw().then(function(a){return phFilterMine(a,phOwner());});};
idbByDate=function(d){return _phByDateRaw(d).then(function(a){return phFilterMine(a,phOwner());});};

idbAdd=function(rec){
  phStamp(rec);
  return _phAddLocal(rec).then(function(r){
    /* upload only what this account owns, and only while it is still signed in */
    if(syncOn()&&rec.blob&&phIsMine(rec,phOwner())){
      pbPhotoUpload(rec).then(function(s){var m=pbPhotoMap();m[rec.id]=s.id;setPbPhotoMap(m);})
