/* ============================================================
   HARDENING — MILESTONE 2: photo pagination & deletion inference
   ------------------------------------------------------------
   pbPhotoList() fetched ONE page of 500 and photoSync treated any
   local photo missing from it as "deleted on another device" — so at
   501 records the oldest photos fell off the page and were deleted
   from the device. Absence is now only evidence of deletion when the
   server set was enumerated COMPLETELY and successfully.
   ============================================================ */

/* @testable-start M2 — pure predicates, no DOM/network */
/* Deletion may be inferred only when ALL of:
     - enumeration of the server set completed successfully,
     - we previously knew this photo was on the server (mapStart),
     - it is absent from the freshly enumerated server set.
   A partial, interrupted, unauthorized or failed enumeration proves
   nothing and must never delete local data. */
function phMayInferDeletion(enumComplete,mapStart,serverById,rec){
  if(!enumComplete)return false;
  if(!rec||!rec.id)return false;
  if(!mapStart||!mapStart[rec.id])return false;
  return !(serverById&&serverById[rec.id]);}
