  if(typeof totalItems==="number"&&totalItems!==collected)return false;
  return true;}
/* @testable-end M2 */

/* Enumerate EVERY page. Resolves {items, complete} — never rejects, so a
   failure degrades to "don't infer deletions" instead of aborting the sync. */
function pbPhotoListAll(){
  var items=[],perPage=200,fetched=0,total=1,totalItems=null;
  function page(p){
    return fetch(pbBase()+"/api/collections/photos/records?perPage="+perPage+"&page="+p
        +"&filter="+encodeURIComponent('user="'+pbUid()+'"')+"&t="+Date.now(),
        {headers:pbHeaders(),cache:"no-store"})
      .then(function(r){return r.ok?r.json():Promise.reject(r.status);})
      .then(function(j){
        items=items.concat(j.items||[]);fetched++;
        total=+j.totalPages||1;
        if(typeof j.totalItems==="number")totalItems=j.totalItems;
        if(p<total)return page(p+1);
        return {items:items,
                complete:phPagesComplete({fetched:fetched,total:total},totalItems,items.length),
                error:null};});}
  return page(1).catch(function(e){return {items:items,complete:false,error:e};});}

/* Full replacement of photoSync: same four phases, but account-scoped (M1) and
   deletion-safe (M2). Kept as one function so the ordering guarantees stay
   obvious — uploads before the deletion pass, deletions last and gated. */
photoSync=function(done){
  if(!syncOn()||pbPhotoSyncing||typeof indexedDB==="undefined"){done&&done();return;}
  pbPhotoSyncing=true;
  var uploaded=0,downloaded=0,removed=0,incomplete=false;
  var mapStart=pbPhotoMap(),map=pbPhotoMap();
  function finish(){
    setPbPhotoMap(map);pbPhotoSyncing=false;
    if(uploaded||downloaded||removed){
      try{wkPhotoKey=null;refreshWeekPhotos();}catch(e){}
      if(state.view==="photos"||state.view==="diary")render();}
    /* FIX-005 / Architect §5: photo enumeration is its OWN cause at its own
       severity — it must not present as the global red "core/training upload
       failed". A complete enumeration (including a complete one that found
       nothing) clears it; a successful CAS commit never does. */
    if(incomplete){try{cfPhotoStatusIncomplete();}catch(e){setSync("error","photo list incomplete — nothing removed");}}
    else {try{cfPhotoStatusComplete();}catch(e){}}
