function scheduleTrainingPushNoBump(ms){clearTimeout(trainingPushTimer);trainingPushTimer=setTimeout(trainingPush,ms||1600);}
scheduleTrainingPush=function(){if(!syncOn())return;revBump("training");scheduleTrainingPushNoBump(1600);};
trainingPush=function(){
