/* ---- recovery snapshots (IndexedDB, account-scoped, bounded) ---- */
var REC_DB="wl_recovery",REC_STORE="snaps",REC_KEEP=3,recDBh=null;
function recDB(){return new Promise(function(res,rej){
  if(recDBh)return res(recDBh);
