  r.onupgradeneeded=function(){var db=r.result;
    if(!db.objectStoreNames.contains(REC_STORE))db.createObjectStore(REC_STORE,{keyPath:"id"});};
  r.onsuccess=function(){recDBh=r.result;res(recDBh);};
  r.onerror=function(){rej(r.error);};});}
function recPut(rec){return recDB().then(function(db){return new Promise(function(res,rej){
  var tx=db.transaction(REC_STORE,"readwrite");tx.objectStore(REC_STORE).put(rec);
  tx.oncomplete=function(){res();};tx.onerror=function(){rej(tx.error);};});});}
function recList(){return recDB().then(function(db){return new Promise(function(res,rej){
  var out=[],tx=db.transaction(REC_STORE,"readonly"),rq=tx.objectStore(REC_STORE).openCursor();
  rq.onsuccess=function(){var c=rq.result;if(c){out.push(c.value);c.continue();}
    else res(out.sort(function(a,b){return b.createdAt-a.createdAt;}));};
  rq.onerror=function(){rej(rq.error);};});});}
function recDelete(id){return recDB().then(function(db){return new Promise(function(res){
  var tx=db.transaction(REC_STORE,"readwrite");tx.objectStore(REC_STORE).delete(id);
  tx.oncomplete=function(){res();};tx.onerror=function(){res();};});});}
/* Snapshot BEFORE anything that can replace non-empty local data.
