    accountId:me,createdAt:Date.now(),appBuild:(typeof APP_BUILD!=="undefined"?APP_BUILD:""),
    reason:reason||"",localRevision:revLocal("core"),trainingRevision:revLocal("training"),
    core:payload(),training:state.training};
  recPut(snap).then(function(){
    return recList().then(function(all){
      var mine=all.filter(function(s){return (s.accountId||"")===me;});
      return Promise.all(mine.slice(REC_KEEP).map(function(s){return recDelete(s.id);}));});})
    .then(function(){cb&&cb(true);}).catch(function(){cb&&cb(false);});}
function recRestore(id,cb){
  recList().then(function(all){
    var s=null;all.forEach(function(x){if(x.id===id)s=x;});
    if(!s){cb&&cb(false);return;}
    recSnapshot("before-restore",function(){
      try{
        applyCloudRaw(s.core);
        if(s.training){state.training=s.training;saveTrainingLocal();}
        revBump("core");revBump("training");   /* restored state is unsynced */
        try{render();}catch(e){}
        cb&&cb(true);
      }catch(e){cb&&cb(false);}});
  }).catch(function(){cb&&cb(false);});}

/* ---- last-agreed fingerprint: the baseline conflict detection needs ---- */
function syncFpGet(){try{return (revAll().serverFp)||"";}catch(e){return "";}}
