      +'font-size:15px;text-align:left">'+esc(o.label)
      +(o.hint?'<div style="font-weight:500;font-size:12px;opacity:.75;margin-top:3px">'+esc(o.hint)+'</div>':'')+'</button>';}).join("");
  wrap.innerHTML='<div style="max-width:420px;width:100%;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px">'
    +'<div style="font-weight:800;font-size:17px;margin-bottom:6px">'+esc(title)+'</div>'
    +'<div style="color:var(--muted);font-size:14px;line-height:1.45">'+esc(msg)+'</div>'+btns+'</div>';
