     otherwise it would be replaced silently (full handling lands in M5) */
  if(!revIsDirty("training"))trainingPull(function(){if(state.view==="train")render();});
  setSync("syncing");
  cloudGet(function(d,err){
    if(err){cfStatusTransportFailure(err,{manual:(typeof manual!=="undefined")&&!!manual});return;}
    var decision=syncDecide({localDirty:isDirty(),localHasData:localHasData(),
      serverHasData:!cloudEmpty(d),serverFp:syncFingerprint(d),lastAgreedFp:syncFpGet()});
    if(decision==="seed"||decision==="push"){cloudPush();return;}
    if(decision==="adopt"){applyCloudSafe(d,"boot-adopt",function(){setLastSync();setSync("ok");render();});return;}
    if(decision==="conflict"){syncEnterConflict(d,"boot");return;}
