/* ============================================================
   HARDENING — COMMIT 1: emergency non-destructive reconciliation
   Authorized by the Product Architect review of Remediation Plan V2.
   Scope is deliberately narrow: stop live data loss. Nothing else.

   Before server-enforced compare-and-swap exists there is NO automatic
   whole-snapshot write of any kind. A fingerprint match cannot stop a
   concurrent write landing after our read, and duplicate rows cannot be
   prevented without the unique index. Uploads become user-initiated and
   preserve the remote copy first. Reduced automation is the accepted
   trade for never losing data silently.
   ============================================================ */

/* @testable-start C1 */
/* Canonical serialization: recursive, key-sorted, array order preserved.
   Exact equality only — the 32-bit fingerprint is never proof of sameness. */
function cfCanon(v){
  if(v===undefined)return "null";
  if(v===null||typeof v!=="object")return JSON.stringify(v);
  if(Array.isArray(v)){var a=[];for(var i=0;i<v.length;i++)a.push(cfCanon(v[i]));return "["+a.join(",")+"]";}
  var k=Object.keys(v).sort(),out=[];
  for(var j=0;j<k.length;j++){if(v[k[j]]===undefined)continue;out.push(JSON.stringify(k[j])+":"+cfCanon(v[k[j]]));}
  return "{"+out.join(",")+"}";}
function cfCanonEq(a,b){try{return cfCanon(a)===cfCanon(b);}catch(e){return false;}}

/* Empty-detection ONLY. Never permission to overwrite dirty state.
   Covers every field in payload(). Deliberately conservative: a false
   "meaningful" only ever prevents an adopt/idle, so over-reporting is safe. */
function coreHasMeaningfulState(d){
  if(!d||typeof d!=="object")return false;
  if((d.weights||[]).length)return true;
  if((d.statuses||[]).length)return true;
  if(Array.isArray(d.presets)&&d.presets.length)return true;
  if(d.weeklySummary||d.nightlySummary)return true;
  var maps=["food","workouts","steps","notes","sleep","bodyfat","waist","skips","nightlyLog","scriptVer","settings"];
  for(var i=0;i<maps.length;i++){var m=d[maps[i]];
    if(m&&typeof m==="object"&&Object.keys(m).length)return true;}
  var g=d.glp;
  if(g&&typeof g==="object"){
    if((g.compounds||[]).length||(g.doses||[]).length||(g.symptoms||[]).length||(g.symptomTypes||[]).length)return true;}
  return false;}

/* Legacy dirty migration, corrected.
   The old rule kept only exact "1" as dirty, so missing/malformed state —
   and any flag the in-flight bug had already wrongly cleared — became
   "clean" and could be adopted over. We cannot tell a legitimate "0" from
   a bug-written one, so EVERY legacy value migrates as dirty. That is not
   permanent: a dirty device whose content is canonically identical to the
   server resolves to "agree" on the next sync and goes clean by itself. */
function legacyDirtyToRevision(){return true;}

/* Cross-account guard. Identity is compared only against owner metadata
   recorded WHILE AUTHENTICATED — never an unverified cached pbCfg().uid,
   which could misattribute one person's data to another. */
function crossAccountVerdict(storedOwnerId,authUserId){
  if(!authUserId)return "unauthenticated";
  if(!storedOwnerId)return "unknown";          /* pre-upgrade install; claimable by this verified login */
  return storedOwnerId===authUserId?"ok":"mismatch";}

/* The decision table. Every branch is named and none writes automatically.
     idle        - nothing to do
     agree       - both sides already identical: record the baseline, go clean
     adopt       - local is clean: taking the server copy is safe
     hold-seed   - server row missing: pending explicit setup, never an auto-POST
     hold-push   - local dirty, server unmoved: pending explicit upload, never an auto-PATCH
     conflict    - ask; never guess
     blocked     - a different account's retained data; do not touch it */
function syncDecideV2(o){
  if(o.accountVerdict==="mismatch")return "blocked";
  var dirty=!!o.localDirty,serverHas=!!o.serverHasData,meaningful=!!o.localMeaningful;
  var eq=(o.localCanon!=null&&o.serverCanon!=null)?(o.localCanon===o.serverCanon):null;
  /* An empty server never overwrites meaningful local data, dirty or not. */
  if(!serverHas)return meaningful?"hold-seed":"idle";
  if(!dirty)return eq===true?"agree":"adopt";
  /* dirty from here down: adoption is unreachable */
  if(!o.baselineTrusted)return eq===true?"agree":"conflict";   /* null (cannot compare) => conflict */
  return o.serverMatchesBaseline===true?"hold-push":"conflict";}
/* @testable-end C1 */

/* ---- verified account ownership (minimal; full scoping lands in Commit 4) ---- */
var CF_OWNER_KEY="cf:lastOwner";
function cfOwnerGet(){try{return localStorage.getItem(CF_OWNER_KEY)||"";}catch(e){return "";}}
function cfOwnerSet(uid){try{if(uid)localStorage.setItem(CF_OWNER_KEY,uid);}catch(e){}}
/* Called only where the identity has just been proven by a successful
   authenticated exchange — not from cached config. */
function cfOwnerStampVerified(){var u=pbUid();if(u)cfOwnerSet(u);}
function cfAccountVerdict(){return crossAccountVerdict(cfOwnerGet(),pbUid());}

/* ---- one-time corrective re-migration of the legacy dirty flag ---- */
(function(){
  var MK="cf:c1mig";
  try{if(localStorage.getItem(MK))return;}catch(e){return;}
  try{
    if(legacyDirtyToRevision()){
      var a=revAll();
      ["core","training"].forEach(function(t){
        var v=a[t]||{local:0,attempted:0,success:0};
        if(!((v.local||0)>(v.success||0)))v.local=(v.success||0)+1;   /* mark dirty without losing history */
        a[t]=v;});
      revSaveAll(a);
      /* durability: only mark migrated if the ledger actually persisted —
         revSaveAll swallows storage errors */
      var chk=revAll();if(!chk.core||!chk.training)return;}
    localStorage.setItem(MK,"1");
  }catch(e){}
})();

/* ---- recovery from EXPLICIT state (the losing side, not the winner) ---- */
/* Minimum viable version of the Commit 2 Recovery Service. Deep-clones
   synchronously at entry so nothing mutates while IndexedDB is awaited,
   and reports verified success so callers can fail closed. */
function cfClone(o){try{return JSON.parse(JSON.stringify(o===undefined?null:o));}catch(e){return null;}}
function cfSnapshotOf(opts,cb){
  var o=opts||{};
  var snap;
  try{
    snap={id:"s_"+Date.now()+"_"+String(Math.random()).slice(2,7),
      accountId:o.accountId||pbUid()||"",createdAt:Date.now(),
      appBuild:(typeof APP_BUILD!=="undefined"?APP_BUILD:""),
      reason:o.reason||"",source:o.source||"local",
      localRevision:revLocal("core"),trainingRevision:revLocal("training"),
      core:cfClone(o.core),training:cfClone(o.training)};
  }catch(e){cb&&cb(false);return;}
  if(snap.core===null&&snap.training===null){cb&&cb(false);return;}
  recPut(snap).then(function(){
    return recList().then(function(all){
      var mine=all.filter(function(s){return (s.accountId||"")===snap.accountId;});
      return Promise.all(mine.slice(REC_KEEP).map(function(s){return recDelete(s.id);}));});})
    .then(function(){cb&&cb(true,snap.id);})
    .catch(function(){cb&&cb(false);});}

/* ---- fail closed: an unverified recovery copy stops the destruction ---- */
applyCloudSafe=function(d,reason,cb){
  var needSnap=false;try{needSnap=coreHasMeaningfulState(payload());}catch(e){needSnap=true;}
  function adopt(){applyCloudRaw(d);syncFpSet(syncFingerprint(d));cfBaselineSet(cfCanon(d));revClean("core");cb&&cb(true);}
  if(!needSnap){adopt();return;}
  cfSnapshotOf({source:"local",reason:reason||"adopt-server",core:payload(),training:state.training},
    function(ok){
      if(!ok){setSync("error","couldn't save a previous copy — nothing was replaced");
        toast("Couldn't save a previous copy. Your data was left as it is.");cb&&cb(false);return;}
      adopt();});};
applyCloud=function(d){applyCloudSafe(d,"apply-cloud");};

/* ---- the agreed baseline, stored as canonical content ---- */
function cfBaselineGet(){try{return (revAll()).canonBaseline||"";}catch(e){return "";}}
function cfBaselineSet(c){var a=revAll();a.canonBaseline=c||"";revSaveAll(a);}

/* ---- gather decision inputs ---- */
function cfInputs(serverData){
  var local=payload();
  var lc=null,sc=null;
  try{lc=cfCanon(local);}catch(e){}
  try{sc=cfCanon(serverData||{});}catch(e){}
  var base=cfBaselineGet();
  return {accountVerdict:cfAccountVerdict(),
    localDirty:isDirty(),localMeaningful:coreHasMeaningfulState(local),
    serverHasData:!cloudEmpty(serverData),localCanon:lc,serverCanon:sc,
    baselineTrusted:!!base,serverMatchesBaseline:!!base&&sc===base};}

/* ---- pending state: visible, and honest that nothing is uploaded yet ---- */
var cfPending=null;   /* "seed" | "push" | null */
function cfSetPending(kind){
  cfPending=kind;
  setSync("error",kind?"changes on this device aren’t uploaded yet — tap to upload":"");}
function cfClearPending(){cfPending=null;}

/* The only upload path before CAS. All four conditions the Architect required:
   fresh fetch, remote copy genuinely preserved, explicit confirmation, and no
   safer merge available. */
function cfUploadNow(){
  if(!syncOn()){toast("Log in first");return;}
  if(cfAccountVerdict()==="mismatch"){toast("This device holds another account’s data — not uploading");return;}
  setSync("syncing");
  cloudGet(function(d,err){
    if(err){setSync(err==="offline"?"offline":"error");toast(err==="offline"?"No connection":"Couldn’t reach the server");return;}
    var i=cfInputs(d);
    if(i.localCanon===i.serverCanon){cfBaselineSet(i.serverCanon);revClean("core");cfClearPending();
      setSync("ok");setLastSync();toast("Already up to date");return;}
    var serverHas=!cloudEmpty(d);
    askConfirm(serverHas
      ? "Upload this device’s data? Your online copy is different — it will be saved as a previous copy first, then replaced."
      : "Upload this device’s data to your account?",
      function(){
        cfSnapshotOf({source:"server",reason:"upload-over-server",core:d,training:(d&&d.training)||null},
          function(ok){
            if(serverHas&&!ok){setSync("error","couldn’t save a previous copy — nothing was uploaded");
              toast("Couldn’t save a previous copy. Nothing was uploaded.");return;}
            var sent=revAttempt("core");
            pbSave({data:payload()},function(saved,e2){
              if(!saved){setSync(e2==="offline"?"offline":"error");toast("Upload failed — your data is still here");return;}
              setLastSync();
              if(revCommit("core",sent)){cfBaselineSet(cfCanon(payload()));syncFpSet(syncFingerprint(payload()));
                cfClearPending();setSync("ok");toast("Uploaded");}
              else{cfSetPending("push");toast("Uploaded — you have newer changes still pending");}});});},
      {label:serverHas?"Replace online copy":"Upload"});});}

/* ---- reconcile: one entry point for boot, login and refresh ---- */
function cfReconcile(d,ctx,done){
  var i=cfInputs(d),decision=syncDecideV2(i);
  function fin(){done&&done(decision);}
  if(decision==="blocked"){
    setSync("error","this device holds another account’s unsynced data");
    toast("This device still has data from a different account. It’s kept safe and untouched.");fin();return;}
  if(decision==="agree"){cfBaselineSet(i.serverCanon);syncFpSet(syncFingerprint(d));revClean("core");
    cfClearPending();setLastSync();setSync("ok");fin();return;}
  if(decision==="adopt"){applyCloudSafe(d,ctx+"-adopt",function(ok){
    if(ok){cfClearPending();setLastSync();setSync("ok");try{render();}catch(e){}}fin();});return;}
  if(decision==="hold-seed"||decision==="hold-push"){cfSetPending(decision==="hold-seed"?"seed":"push");fin();return;}
  if(decision==="conflict"){cfEnterConflict(d,ctx);fin();return;}
  setSync("ok");fin();}

/* ---- conflict: preserve the side that is about to be destroyed ---- */
function cfEnterConflict(d,ctx){
  setSync("error","changes in two places — needs your decision");
  wlChoose("We found changes in two places",
    "This device has changes that haven’t been uploaded, and your online copy changed too. Nothing has been replaced.",
    [{label:"Use changes from this device",hint:"The online version will be saved as a previous copy first",primary:true},
     {label:"Use the online version",hint:"This device’s version will be saved as a previous copy first"},
     {label:"Decide later",hint:"Keep both versions unchanged"}],
    function(i){
      if(i===0){
        /* the REMOTE copy is the losing side here — it is what gets preserved */
        cfSnapshotOf({source:"server",reason:"keep-device-over-online",core:d,training:(d&&d.training)||null},
          function(ok){
            if(!ok){setSync("error","couldn’t save a previous copy — nothing was replaced");
              toast("Couldn’t save your online copy, so nothing was replaced.");return;}
            cfUploadNow();});
        return;}
      if(i===1){applyCloudSafe(d,"use-online-copy",function(ok){
        if(ok){cfClearPending();setLastSync();setSync("ok");try{render();}catch(e){}toast("Now using your online copy");}});return;}
      setSync("error","changes in two places — not yet resolved");});}

/* ---- rewire boot, refresh and login onto the safe path ---- */
autoSync=function(){
  if(!syncOn())return;
  try{phAccountChanged();}catch(e){}
  if(cfAccountVerdict()==="mismatch"){setSync("error","this device holds another account’s unsynced data");return;}
  pullConnections();
  if(!revIsDirty("training"))trainingPull(function(){if(state.view==="train")render();});
  setSync("syncing");
  cloudGet(function(d,err){
    if(err){cfStatusTransportFailure(err,{manual:(typeof manual!=="undefined")&&!!manual});return;}
    cfOwnerStampVerified();
    cfReconcile(d,"boot");});};

cloudPull=function(manual,done){
  setSync("syncing");
  cloudGet(function(d,err){
    if(err){cfStatusTransportFailure(err,{manual:(typeof manual!=="undefined")&&!!manual});
      if(manual)toast(err==="offline"?"No connection":err==="auth"?"Please log in again":"Couldn’t refresh");done&&done();return;}
    cfOwnerStampVerified();
    cfReconcile(d,"refresh",function(dec){
      if(manual){
        if(dec==="agree"||dec==="adopt")toast("Up to date");
        else if(dec==="hold-push"||dec==="hold-seed")toast("Your changes are still on this device — tap the status to upload");}
      done&&done();});});};

/* Explicit destructive replacement keeps its confirm, and now fails closed. */
syncReplaceWithServer=function(){
  askConfirm("Replace this device with the online copy? Anything on this device that hasn’t been uploaded will be replaced. A previous copy is saved first.",
    function(){setSync("syncing");
      cloudGet(function(d,err){
        if(err){cfStatusTransportFailure(err,{manual:true});toast("Couldn’t reach the server");return;}
        applyCloudSafe(d,"explicit-replace",function(ok){
          if(ok){cfClearPending();setLastSync();setSync("ok");try{render();}catch(e){}toast("This device now matches your online copy");}});});},
    {label:"Replace this device",danger:true});};

/* Restore must not destroy the current state if its own snapshot fails. */
recRestore=function(id,cb){
  recList().then(function(all){
    var s=null;all.forEach(function(x){if(x.id===id)s=x;});
    if(!s){cb&&cb(false);return;}
    cfSnapshotOf({source:"local",reason:"before-restore",core:payload(),training:state.training},function(ok){
      if(!ok){toast("Couldn’t save a previous copy. Nothing was restored.");cb&&cb(false);return;}
      try{applyCloudRaw(s.core);
        if(s.training){state.training=s.training;saveTrainingLocal();}
        revBump("core");revBump("training");cfSetPending("push");
        try{render();}catch(e){}cb&&cb(true);
      }catch(e){cb&&cb(false);}});
  }).catch(function(){cb&&cb(false);});};

/* Logout must not wipe the device on an unverified snapshot. */
pbLogout=function(){
  function wipe(){
    cfSnapshotOf({source:"local",reason:"before-logout",core:payload(),training:state.training},function(ok){
      if(!ok){toast("Couldn’t save a previous copy, so this device wasn’t cleared. You’re still signed in.");return;}
      pbForceLogout();location.reload();});}
  if(revAnyDirty()||cfPending){
    wlChoose("You have changes that aren’t uploaded",
      "Logging out clears this device’s copy. Upload your changes first so nothing is lost.",
      [{label:"Upload first",primary:true},
       {label:"Log out anyway",hint:"A previous copy is saved on this device first"},
       {label:"Cancel"}],
      function(i){
        if(i===0){cfUploadNow();return;}          /* no timer: the user logs out again once it succeeds */
        if(i===1){wipe();return;}});
    return;}
  askConfirm("Log out on this device? Your data stays safe online — log back in any time.",wipe,{label:"Log out",danger:true});};

/* Login: stamp verified ownership, refuse another account's retained data. */
pbDoLogin=function(){
  if(pbLoginState.busy)return;
  var em=(document.getElementById("wl-pb-email")||{}).value||"";
  var pw=(document.getElementById("wl-pb-pass")||{}).value||"";
