  try{core=localStorage.getItem(KEY)||"";train=localStorage.getItem(TKEY)||"";}catch(e){}
  try{
    localStorage.setItem("cf:quarantine:"+stamp+":core",core);
    localStorage.setItem("cf:quarantine:"+stamp+":training",train);
    if(localStorage.getItem("cf:quarantine:"+stamp+":core")!==core||
       localStorage.getItem("cf:quarantine:"+stamp+":training")!==train){
      toast("Couldn’t set that data aside safely — nothing was changed");return;}
    localStorage.setItem(CF_QUAR_FLAG,stamp);
    localStorage.removeItem(KEY);localStorage.removeItem(TKEY);localStorage.removeItem(WOKEY);
    localStorage.removeItem(REV_KEY);                        /* stale unscoped sync metadata goes with it */
  }catch(e){toast("Couldn’t set that data aside — nothing was changed");return;}
  location.reload();};
document.addEventListener("click",function(e){
  var t=e.target&&e.target.closest&&e.target.closest('[data-act="cf:signout"]');
  if(!t)return;e.preventDefault();e.stopPropagation();
  pbClearSession(true);try{render();}catch(err){location.reload();}
},true);

/* ---- reconciliation inputs: ONE normalized representation everywhere ---- */
function cfInputs(serverData){
  var ln=null,sn=null,lm=false,sm=false;
  try{var lN=cfNormalize(payload());ln=cfCanon(lN);lm=cfIsMeaningfulNormalized(lN);}catch(e){}
  try{var sN=cfNormalize(serverData||{});sn=cfCanon(sN);sm=cfIsMeaningfulNormalized(sN);}catch(e){}
  var base=cfBaselineGet();
  return {accountVerdict:cfAccountVerdict(),
    localDirty:isDirty(),localMeaningful:lm,serverHasData:sm,
    localCanon:ln,serverCanon:sn,
    baselineTrusted:!!base,serverMatchesBaseline:!!base&&sn===base};}

applyCloudSafe=function(d,reason,cb){
  var needSnap=false;try{needSnap=coreHasMeaningfulState(payload());}catch(e){needSnap=true;}
  function adopt(){applyCloudRaw(d);
    cfBaselineSet(cfCanon(cfNormalize(d)));syncFpSet(syncFingerprint(d));revClean("core");cb&&cb(true);}
  if(!needSnap){adopt();return;}
  cfSnapshotOf({source:"local",reason:reason||"adopt-server",accountId:cfLocalOwnerId(),
    core:payload(),training:state.training},
    function(ok){
      if(!ok){setSync("error","couldn't save a previous copy — nothing was replaced");
        toast("Couldn't save a previous copy. Your data was left as it is.");cb&&cb(false);return;}
      adopt();});};
applyCloud=function(d){applyCloudSafe(d,"apply-cloud");};

cfReconcile=function(d,ctx,done){
  var i=cfInputs(d),decision=syncDecideV2(i);
  function fin(){done&&done(decision);}
  if(decision==="blocked"){setSync("error","this device holds another account’s unsynced data");fin();return;}
  if(decision==="idle"){
    /* semantic empty/empty: the conservative migration's dirty state must
       clear here, or a fresh install shows a pending badge forever */
    if(isDirty()&&!i.localMeaningful&&!i.serverHasData){
      cfBaselineSet(i.localCanon||"");revClean("core");cfClearPending();}
    if(revIsDirty("training")&&!cfTrainingMeaningful(state.training))revClean("training");
    setSync("ok");fin();return;}
  if(decision==="agree"){cfBaselineSet(i.serverCanon);syncFpSet(syncFingerprint(d));revClean("core");
    if(revIsDirty("training")&&!cfTrainingMeaningful(state.training))revClean("training");
    cfClearPending();setLastSync();setSync("ok");fin();return;}
  if(decision==="adopt"){applyCloudSafe(d,ctx+"-adopt",function(ok){
    if(ok){cfClearPending();setLastSync();setSync("ok");try{render();}catch(e){}}fin();});return;}
  if(decision==="hold-seed"||decision==="hold-push"){cfSetPending(decision==="hold-seed"?"seed":"push");fin();return;}
  if(decision==="conflict"){cfEnterConflict(d,ctx);fin();return;}
  setSync("ok");fin();};

/* conflict pre-CAS: nothing can overwrite the server; keep-device holds pending
   after genuinely preserving the online copy (owned by the SERVER account) */
cfEnterConflict=function(d,ctx){
  setSync("error","changes in two places — needs your decision");
  wlChoose("We found changes in two places",
    "This device has changes that haven’t been uploaded, and your online copy changed too. Nothing has been replaced.",
    [{label:"Keep this device’s changes",hint:"Kept here and uploaded when the sync fix ships; the online version is saved as a previous copy now",primary:true},
     {label:"Use the online version",hint:"This device’s version is saved as a previous copy first"},
     {label:"Decide later",hint:"Keep both versions unchanged"}],
    function(i){
      if(i===0){
        cfSnapshotOf({source:"server",reason:"keep-device-pending",accountId:pbUid()||"server",
          core:d,training:(d&&d.training)||null},
          function(ok){
            if(!ok){setSync("error","couldn’t save a previous copy — nothing was decided");
              toast("Couldn’t save your online copy. Nothing was changed.");return;}
            cfSetPending("push");
            toast("Kept. Your changes upload when the sync fix ships.");});
        return;}
      if(i===1){applyCloudSafe(d,"use-online-copy",function(ok){
        if(ok){cfClearPending();setLastSync();setSync("ok");try{render();}catch(e){}toast("Now using your online copy");}});return;}
      setSync("error","changes in two places — not yet resolved");});};

/* ---- boot / pull / login: gated stamping, claim pauses reconciliation ---- */
autoSync=function(){
  if(!syncOn())return;
  try{phAccountChanged();}catch(e){}
  var blocked=cfAccountBlocked();
  if(blocked){setSync("error",blocked==="mismatch"?"this device holds another account’s unsynced data":"is this your data? — needs your answer");
    try{render();}catch(e){}return;}
  cfOwnerMaybeStamp();
  pullConnections();
  if(revIsDirty("training")&&!cfTrainingMeaningful(state.training))revClean("training");
  if(!revIsDirty("training"))trainingPull(function(){if(state.view==="train")render();});
  setSync("syncing");
  cloudGet(function(d,err){
    if(err){cfStatusTransportFailure(err,{manual:(typeof manual!=="undefined")&&!!manual});return;}
    cfReconcile(d,"boot");});};

cloudPull=function(manual,done){
  var blocked=cfAccountBlocked();
  if(blocked){try{render();}catch(e){}done&&done();return;}
  setSync("syncing");
  cloudGet(function(d,err){
    if(err){cfStatusTransportFailure(err,{manual:(typeof manual!=="undefined")&&!!manual});
      if(manual)toast(err==="offline"?"No connection":err==="auth"?"Please log in again":"Couldn’t refresh");done&&done();return;}
    cfOwnerMaybeStamp();
    cfReconcile(d,"refresh",function(dec){
      if(manual){
        if(dec==="agree"||dec==="adopt"||dec==="idle")toast("Up to date");
        else if(dec==="hold-push"||dec==="hold-seed")toast("Your changes are still on this device — they upload when the sync fix ships");}
      done&&done();});});};

pbDoLogin=function(){
  if(pbLoginState.busy)return;
  var em=(document.getElementById("wl-pb-email")||{}).value||"";
  var pw=(document.getElementById("wl-pb-pass")||{}).value||"";
  var bs=(document.getElementById("wl-pb-base")||{}).value||"";
  var rmEl=document.getElementById("wl-pb-remember");
  var remember=rmEl?!!rmEl.checked:true;
  pbLoginState.remember=remember;em=em.trim();
  if(!em||!pw){pbLoginState.err="Enter your email and password.";pbRenderLogin();return;}
  if(bs){var c=pbCfg();c.base=bs.trim();setPbCfg(c);}
  pbLoginState.busy=true;pbLoginState.err="";pbRenderLogin();
  pbLogin(em,pw,function(ok,why){
    pbLoginState.busy=false;
    if(!ok){pbLoginState.err=(why==="bad")?"That email and password don’t match.":(why==="offline")?"Can’t reach the server. Is Tailscale on?":"Something went wrong. Try again.";
      pbRenderLogin();return;}
    pbLoginState.err="";
    /* STATUS-V3-02: reauthentication is the ONLY thing that clears `auth`, and
       it clears nothing else — a network or manual failure survives a sign-in. */
    try{cfStatusAuthOk();}catch(e){}
    try{phAccountChanged();phRefreshOrphanCount();}catch(e){}
    var blocked=cfAccountBlocked();
    if(blocked){ /* claim/mismatch screen decides; reconciliation is PAUSED, no stamp */
      try{document.documentElement.style.visibility="";}catch(e){}
      render();return;}
    cfOwnerMaybeStamp();
    setSync("syncing");
    cloudGet(function(d,err){
      function finish(){
        trainingPull(function(){
          setLastSync();render();
          toast("Welcome back"+(state.settings.name?(", "+state.settings.name):""));
          photoSync(function(r){if(r&&r.downloaded)toast(r.downloaded+" photo"+(r.downloaded===1?"":"s")+" restored");});}); }
      if(err||!d){setSync(err==="offline"?"offline":"error");finish();return;}
      cfReconcile(d,"login",function(){finish();});});},remember);};

recRestore=function(id,cb){
  recList().then(function(all){
    var s=null;all.forEach(function(x){if(x.id===id)s=x;});
    if(!s){cb&&cb(false);return;}
    cfSnapLocal("before-restore",function(ok){
      if(!ok){toast("Couldn’t save a previous copy. Nothing was restored.");cb&&cb(false);return;}
      try{applyCloudRaw(s.core);
        if(s.training){state.training=s.training;saveTrainingLocal();}
        revBump("core");revBump("training");cfSetPending("push");
        try{render();}catch(e){}cb&&cb(true);
      }catch(e){cb&&cb(false);}});
  }).catch(function(){cb&&cb(false);});};

pbLogout=function(){
  function wipe(){
    cfSnapLocal("before-logout",function(ok){
      if(!ok){toast("Couldn’t save a previous copy, so this device wasn’t cleared. You’re still signed in.");return;}
      pbForceLogout();location.reload();});}
  if(revAnyDirty()||cfPending){
    wlChoose("You have changes that aren’t uploaded",
      "Uploading is paused until the sync fix ships, so logging out now would clear changes that exist only on this device.",
      [{label:"Stay signed in",primary:true},
       {label:"Save a copy to my files first",hint:"Downloads a backup, then you can decide"},
       {label:"Log out anyway",hint:"A previous copy is saved on this device first"}],
      function(i){
        if(i===1){try{exportData();}catch(e){toast("Couldn’t export");}return;}
        if(i===2){wipe();return;}});
    return;}
  askConfirm("Log out on this device? Your data stays safe online — log back in any time.",wipe,{label:"Log out",danger:true});};

/* ---- export/import carry training too; honest about contents ---- */
backupJSON=function(){
  var p=payload();
  return JSON.stringify(Object.assign({},p,{training:state.training,backupVersion:2}),null,2);};
applyImport=function(text){
  var d;try{d=JSON.parse(text);}catch(err){toast("That isn't valid backup data");return;}
  if(!d||typeof d!=="object"||(!("weights" in d)&&!("settings" in d))){toast("Unrecognized backup format");return;}
  cfSnapLocal("before-import",function(ok){
    if(!ok){toast("Couldn’t save a previous copy. Nothing was imported.");return;}
    askConfirm("Replace all data on this device with this backup? Current entries will be overwritten.",function(){
      state.settings=Object.assign({},DEFAULT_SETTINGS,d.settings||{});
      state.weights=Array.isArray(d.weights)?d.weights:[];
      state.food=d.food||{};state.workouts=d.workouts||{};state.steps=d.steps||{};state.notes=d.notes||{};state.sleep=d.sleep||{};state.bodyfat=d.bodyfat||{};state.waist=d.waist||{};state.statuses=d.statuses||[];state.weeklySummary=d.weeklySummary||null;state.nightlySummary=d.nightlySummary||null;state.nightlyLog=d.nightlyLog||{};state.skips=d.skips||{};state.glp=d.glp||glpDefault();
      state.presets=(Array.isArray(d.presets)&&d.presets.length)?d.presets:DEFAULT_PRESETS.slice();
      if(d.training&&typeof d.training==="object"){state.training=Object.assign({},state.training,d.training);saveTrainingLocal();revBump("training");}
      glpNormalize();
      state.pasteOpen=false;state.view="overview";applyTheme(state.settings.theme||"dark");save();
      toast("Data restored"+(d.training?"":" (this backup has no training data)"));
    },{label:"Replace",danger:false});});};

/* ---- final render gate + reveal: the boot guard's decision point ----
   The gate must paint the confirmation overlay too. "No — set it aside" runs
   through askConfirm, which queues state.pendingConfirm and calls render() to
   draw the dialog — but this gate replaces #app and returns, and
   confirmOverlayHTML() is otherwise only appended by the main app render and
   the login render. So the dialog could never appear and the button did
   nothing, forever: found on a real iPhone during the day-one canary smoke,
   with the athlete stuck at the gate and the only working control being an
   unsafe "Yes — this is mine". Every confirm-driven action reachable from
   this screen was dead the same way. The confirm:yes/no handlers are bound at
   document level, so painting the overlay is the whole fix.
   (The earlier gate at ~9765 has the same shape but is unreachable: render
   was reassigned again below it, and _cfRender captured the pre-gate render.) */
render=function(){
  var b=cfAccountBlocked();
  if(b){var el=document.getElementById("app")||document.body;
    try{el.innerHTML=cfBlockedHTML(b)+confirmOverlayHTML();}catch(e){}
    try{document.documentElement.style.visibility="";}catch(e){}
    return;}
  _cfRender();
  try{document.documentElement.style.visibility="";}catch(e){}};
try{render();}catch(e){try{document.documentElement.style.visibility="";}catch(e2){}}


/* ============================================================
   HARDENING — COMMIT 1d: Commit 1c re-review corrections
   Four required changes: (1) Coach Max result handling was the last
   silent adopt-over-dirty path — the recap poll ended in a full-snapshot
   applyCloud up to 7 minutes after its clean-check; (2) set-aside deleted
   the workout draft it had itself deemed meaningful; (3) equality excluded
   user-editable settings (startDate/macroAuto/calTargetAuto), hiding real
   intent divergence; (4) unclaimed export removed — unknown owner is not
   proof of ownership.
   ============================================================ */

/* @testable-start C1D */
/* Synchronization equality vs default normalization, separated (Blocker 3).
   - macroAuto / calTargetAuto: USER-EDITABLE INTENT. Included in equality
     with stable semantic defaults (true = automatic), never excluded.
   - startDate: user-editable, but its generated default is todayISO() — a
     moving target. Rule: included when settings.startDateSet is true (the
     UI sets it on any user edit). For legacy rows without the flag, the
     deterministic, symmetric rule is: included iff the payload has weights
     (an engaged athlete's start date is real intent; a fresh install's
     generated date is noise). Documented in COMMIT1D_NOTES.md.
   - onboarded: DERIVED DEVICE/UI STATE — init re-derives it from data
     presence, so it carries no independent user intent. Excluded, by
     documented policy.
   - scriptVer: implementation metadata. Excluded. */
function cfSettingsForEquality(settings,hasWeights,DEFS,canon){
  var SYNC_DEFAULTS={macroAuto:true,calTargetAuto:true,startDateSet:false};
  var EXCLUDE={onboarded:1,seenNightly:1};
  var merged=Object.assign({},DEFS,SYNC_DEFAULTS,settings||{}),out={},k;
  /* the legacy rule must read the RAW flag — merged always carries the
     default false, which would make the weights-based branch dead code */
  var rawFlag=(settings||{}).startDateSet;
  var includeStart=rawFlag===true||( rawFlag===undefined&&!!hasWeights&&!!(settings||{}).startDate );
  for(k in merged){
    if(!Object.prototype.hasOwnProperty.call(merged,k))continue;
    if(EXCLUDE[k])continue;
    if(k==="startDate"){if(includeStart&&merged[k])out[k]=merged[k];continue;}
    var def=Object.prototype.hasOwnProperty.call(SYNC_DEFAULTS,k)?SYNC_DEFAULTS[k]:DEFS[k];
    if(canon(merged[k])===canon(def))continue;
    out[k]=merged[k];}
  return out;}

function cfNormalizeWith(d,DEFS,DPRE,canon){
  d=d||{};DEFS=DEFS||{};DPRE=DPRE||[];
  var o={},i,k;
  var hasWeights=(d.weights||[]).length>0;
  var s=cfSettingsForEquality(d.settings,hasWeights,DEFS,canon);
  if(Object.keys(s).length)o.settings=s;
  var arrs=["weights","statuses"];
  for(i=0;i<arrs.length;i++)if((d[arrs[i]]||[]).length)o[arrs[i]]=d[arrs[i]];
  var maps=["food","workouts","steps","notes","sleep","bodyfat","waist","skips","nightlyLog"];
  for(i=0;i<maps.length;i++){var m=d[maps[i]];
    if(m&&typeof m==="object"&&Object.keys(m).length)o[maps[i]]=m;}
  if(d.weeklySummary)o.weeklySummary=d.weeklySummary;
  if(d.nightlySummary)o.nightlySummary=d.nightlySummary;
  if(Array.isArray(d.presets)&&d.presets.length&&canon(d.presets)!==canon(DPRE))o.presets=d.presets;
  var g=d.glp;
  if(g&&typeof g==="object"){
    var GDEF={enabled:false,showDueDate:true,titration:false,siteRotation:true,symptomLogging:true};
    var gg={},gs=Object.assign({},GDEF,g.settings||{}),gsOut={};
    for(k in gs){if(canon(gs[k])!==canon(GDEF[k]))gsOut[k]=gs[k];}
    if(Object.keys(gsOut).length)gg.settings=gsOut;
    if(g.compound)gg.compound=g.compound;
    if((g.doses||[]).length)gg.doses=g.doses;
    if((g.symptoms||[]).length)gg.symptoms=g.symptoms;
    var st=[];(g.symptomTypes||[]).forEach(function(x){
      if(!x)return;
      if(x.isBuiltIn){if(x.archived)st.push({label:x.label,archived:true,builtIn:true});}
      else st.push(x);});
    if(st.length)gg.symptomTypes=st;
    if(Object.keys(gg).length)o.glp=gg;}
  return o;}

/* Merge ONLY the server-owned recap fields. Never touches athlete data,
   never marks anything clean, never sets a baseline (Blocker 1). */
function cfCoachFieldsOf(d,day){
  var out={};
  if(d&&d.nightlyLog&&d.nightlyLog[day])out.nightly=d.nightlyLog[day];
  if(d&&d.nightlySummary)out.nightlySummary=d.nightlySummary;
  if(d&&d.weeklySummary)out.weeklySummary=d.weeklySummary;
  return out;}
/* @testable-end C1D */

cfNormalize=function(d){
  return cfNormalizeWith(d,
    (typeof DEFAULT_SETTINGS!=="undefined")?DEFAULT_SETTINGS:{},
    (typeof DEFAULT_PRESETS!=="undefined")?DEFAULT_PRESETS:[],
    cfCanon);};

/* startDateSet: stamped the moment the athlete edits the start-date field.
   Capture phase so it works regardless of which existing handler consumes
   the change. */
document.addEventListener("change",function(e){
  var t=e.target;
  if(t&&t.getAttribute&&t.getAttribute("data-set")==="startDate"){
    state.settings.startDateSet=true;}
},true);

/* ---- Coach Max: recap merge only, re-checked on arrival (Blocker 1) ---- */
function mergeCoachResultOnly(day,d){
  var f=cfCoachFieldsOf(d,day);
  if(!f.nightly||!f.nightly.text)return false;
  state.nightlyLog=state.nightlyLog||{};
  state.nightlyLog[day]=f.nightly;
  if(f.nightlySummary)state.nightlySummary=f.nightlySummary;
  if(f.weeklySummary)state.weeklySummary=f.weeklySummary;
  saveLocal();          /* recap is server-authored; not a new athlete edit */
  return true;}

genNightly=function(){
  if(!syncOn()){toast("Log in first");return;}
  if(state.nightBusy||state.genBusy)return;
  if(cfAccountVerdict()!=="ok"){toast("Sort out this device’s account data first");return;}
  var sel=state.selDate,uid0=pbUid();
  var miss=dayMissing(sel);
  if(miss.length){toast("Log "+miss.join(", ")+" first to complete "+(sel===todayISO()?"today":"this day"));return;}
  state.nightBusy=true;render();
  var prevGen=(state.nightlyLog&&state.nightlyLog[sel]&&state.nightlyLog[sel].generated)||null;
  /* fresh reconcile FIRST — a clean check at request start is only meaningful
     against the server's current content (Architect ruling B) */
  new Promise(function(res,rej){
    cloudGet(function(d,err){
      if(err){rej(new Error(err==="offline"?"No connection":"Couldn't reach your server"));return;}
      cfReconcile(d,"coach-preflight",function(){res();});});
  }).then(function(){
    return pushDataPromise();                       /* rejects honestly if dirty */
  }).then(function(){
    return new Promise(function(res,rej){
      pbSave({coachreq:{day:sel,ts:Date.now()}},function(ok){ok?res():rej(new Error("Couldn't reach your server"));});});
  }).then(function(){
    return new Promise(function(resolve){
      var n=0,MAX=70;
      function tick(){n++;
        pbGetRecord(function(rec){
          var d=rec&&rec.data;
          var got=d&&d.nightlyLog&&d.nightlyLog[sel];
          if(got&&got.text&&got.generated!==prevGen){resolve(d);return;}
          if(n>=MAX){resolve(null);return;}
          setTimeout(tick,6000);});}
      setTimeout(tick,8000);});
  }).then(function(d){
    state.nightBusy=false;
    /* arrival re-checks: same account, and NEVER a full-snapshot adoption */
    if(pbUid()!==uid0||cfAccountVerdict()!=="ok"){render();return;}
    if(d){
      var merged=mergeCoachResultOnly(sel,d);
      state.settings.seenNightly=sel;saveLocal();
      if(!revIsDirty("core")){
        /* still clean: safe reconciliation (which re-checks dirty itself) */
        cfReconcile(d,"coach-result",function(){});
      } /* dirty: local edits made during the poll stay untouched and pending */
      state.nightOpen=true;
      toast(merged?((sel===todayISO()?"Today":"That day")+"’s recap is ready"):"Still working — it will appear here shortly");
    }else toast("Still working — it will appear here shortly");
    render();
  }).catch(function(e){state.nightBusy=false;render();toast(e.message||"Couldn’t generate");});};

/* ---- set-aside: the COMPLETE meaningful set, all-or-nothing (Blocker 2) ---- */
cfDisownLocal=function(){
  var stamp=String(Date.now());
  var KEYS={core:KEY,training:TKEY,workout:WOKEY};
  var src={},qk={},k;
  try{for(k in KEYS)src[k]=localStorage.getItem(KEYS[k])||"";}catch(e){toast("Couldn’t read this device’s data — nothing was changed");return;}
  try{
    for(k in KEYS){qk[k]="cf:quarantine:"+stamp+":"+k;localStorage.setItem(qk[k],src[k]);}
    for(k in KEYS){if(localStorage.getItem(qk[k])!==src[k])throw new Error("verify "+k);}
    /* manifest LAST — its presence certifies a complete, verified set */
    localStorage.setItem("cf:quarantine:"+stamp+":manifest",JSON.stringify({
      stamp:stamp,createdAt:Date.now(),appBuild:(typeof APP_BUILD!=="undefined"?APP_BUILD:""),
      keys:Object.keys(KEYS),sizes:{core:src.core.length,training:src.training.length,workout:src.workout.length}}));
    if(!localStorage.getItem("cf:quarantine:"+stamp+":manifest"))throw new Error("verify manifest");
    localStorage.setItem(CF_QUAR_FLAG,stamp);
    for(k in KEYS)localStorage.removeItem(KEYS[k]);
    localStorage.removeItem(REV_KEY);
  }catch(e){
    /* fail closed: remove partial quarantine copies, keep every source */
    try{for(k in KEYS)localStorage.removeItem(qk[k]||"");localStorage.removeItem("cf:quarantine:"+stamp+":manifest");}catch(e2){}
    toast("Couldn’t set that data aside safely — nothing was changed");return;}
  location.reload();};

/* ---- unclaimed screen: NO export before ownership is proven (Required 4).
   Export lives in the signed-out recovery flow below, which never associates
   the data with a newly authenticated account. ---- */
cfBlockedHTML=function(kind){
  var open='<div style="max-width:520px;margin:0 auto;padding:28px 20px">';
  if(kind==="mismatch")
    return open+
      '<div style="font-size:20px;font-weight:800;margin-bottom:10px">Data from another account</div>'+
      '<div style="opacity:.85;line-height:1.5;margin-bottom:18px">This device still has data from a different account that was never uploaded. It’s kept exactly as it is, and it stays hidden. To use or save that data, sign in as the account it belongs to.</div>'+
      '<button class="wl-btn wl-btn-primary wl-full" data-act="cf:signout" style="margin-bottom:10px">Switch account</button>'+
      '<button class="wl-btn wl-btn-ghost wl-full" data-act="cf:signout">Sign out</button></div>';
  return open+
    '<div style="font-size:20px;font-weight:800;margin-bottom:10px">Is this your data?</div>'+
    '<div style="opacity:.85;line-height:1.5;margin-bottom:18px">There’s data already on this device from before you signed in. We won’t add it to your account without asking.</div>'+
    '<button class="wl-btn wl-btn-primary wl-full" data-act="cf:claim" style="margin-bottom:10px">Yes — this is mine</button>'+
    '<button class="wl-btn wl-btn-ghost wl-full" data-act="cf:disown" style="margin-bottom:10px">No — set it aside</button>'+
