/* ============================================================
   HARDENING — COMMIT 1e: Commit 1d re-review corrections
   (1) Every async destructive adoption is now revision- and account-
   conditional — the Architect reproduced an edit made during the recovery
   wait being overwritten and marked clean. (2) Coach preflight outcomes are
   enforced — a failed adoption no longer lets the request proceed. (3) The
   coach request carries an immutable context checked at every step — a
   uid-only check missed the A→B→A round trip. (4) Quarantine cleanup is
   phase-aware — a deletion exception can no longer roll back a committed
   recovery set. Plus the pairwise legacy startDate rule.
   ============================================================ */

/* @testable-start C1E */
/* Legacy startDate rule, corrected (Architect judgment B): "has weigh-ins"
   was too narrow an engagement proxy — an athlete with goals, nutrition,
   notes or GLP config but no weigh-ins still owns their start date. Rule:
   flag true → always compare; flag absent → compare when the payload has ANY
   meaningful non-startDate state; ignore only when otherwise semantically
   empty. Residual (documented): a legacy user whose ONLY change was the
   start date is indistinguishable from a generated fresh-install date. */
function cfStartDateIncluded(rawFlag,restMeaningful,hasStartDate){
  if(rawFlag===true)return !!hasStartDate;
  if(rawFlag===undefined)return !!hasStartDate&&!!restMeaningful;
  return false;}

/* Adoption context: captured before the async recovery wait, verified
   immediately before the overwrite. Any drift aborts the adoption. */
function cfAdoptionStale(ctx,now){
  return ctx.owner!==now.owner||ctx.gen!==now.gen||ctx.rev!==now.rev;}

/* Coach request context validity — checked before the operational write,
   before every poll, inside every poll callback, and before the merge. */
function cfCoachCtxValid(ctx,now){
  return ctx.owner===now.owner&&ctx.gen===now.gen&&ctx.tok===now.tok;}
/* @testable-end C1E */

