/* ---- revision-conditional adoption (Required finding 1) ---- */
applyCloudSafe=function(d,reason,cb){
  var ctx={owner:pbUid(),gen:CF_SESSION_GEN,rev:revLocal("core")};
  var needSnap=false;try{needSnap=coreHasMeaningfulState(payload());}catch(e){needSnap=true;}
  function adopt(){
    var now={owner:pbUid(),gen:CF_SESSION_GEN,rev:revLocal("core")};
    if(cfAdoptionStale(ctx,now)){
      /* an edit or account change landed during the async recovery wait —
         the overwrite is aborted; the recovery copy is kept */
      setSync("error","changes arrived while syncing — nothing was replaced");
      cb&&cb(false,"stale");return;}
    applyCloudRaw(d);
    cfBaselineSet(cfCanon(cfNormalize(d)));syncFpSet(syncFingerprint(d));revClean("core");cb&&cb(true);}
  if(!needSnap){adopt();return;}
  cfSnapshotOf({source:"local",reason:reason||"adopt-server",accountId:cfLocalOwnerId(),
    core:payload(),training:state.training},
    function(ok){
      if(!ok){setSync("error","couldn't save a previous copy — nothing was replaced");
        toast("Couldn't save a previous copy. Your data was left as it is.");cb&&cb(false,"recovery");return;}
      adopt();});};
applyCloud=function(d){applyCloudSafe(d,"apply-cloud");};

/* ---- reconciliation outcomes (Required finding 2) ---- */
cfReconcile=function(d,ctx,done){
  var i=cfInputs(d),decision=syncDecideV2(i);
  function fin(outcome){done&&done(decision,Object.assign({decision:decision,completed:false},outcome||{}));}
  if(decision==="blocked"){setSync("error","this device holds another account’s unsynced data");fin({blocked:true});return;}
  if(decision==="idle"){
    if(isDirty()&&!i.localMeaningful&&!i.serverHasData){
      cfBaselineSet(i.localCanon||"");revClean("core");cfClearPending();}
    if(revIsDirty("training")&&!cfTrainingMeaningful(state.training))revClean("training");
    setSync("ok");fin({completed:true});return;}
  if(decision==="agree"){cfBaselineSet(i.serverCanon);syncFpSet(syncFingerprint(d));revClean("core");
    if(revIsDirty("training")&&!cfTrainingMeaningful(state.training))revClean("training");
    cfClearPending();setLastSync();setSync("ok");fin({completed:true});return;}
  if(decision==="adopt"){applyCloudSafe(d,ctx+"-adopt",function(ok,why){
    if(ok){cfClearPending();setLastSync();setSync("ok");try{render();}catch(e){}fin({completed:true,adopted:true});}
    else if(why==="stale"){
      /* re-reconcile once against the same fetch: the new dirty state routes
         to hold/conflict correctly; depth-guarded against loops */
      if(ctx.slice(-6)==="-retry"){fin({stale:true});return;}
      cfReconcile(d,ctx+"-retry",done);}
    else fin({recoveryFailed:true});});return;}
  if(decision==="hold-seed"||decision==="hold-push"){cfSetPending(decision==="hold-seed"?"seed":"push");fin({pending:true});return;}
  if(decision==="conflict"){cfEnterConflict(d,ctx);fin({conflict:true});return;}
  setSync("ok");fin({completed:true});};

/* ---- Coach Max with an immutable request context (Required finding 3) ---- */
genNightly=function(){
  if(!syncOn()){toast("Log in first");return;}
  if(state.nightBusy||state.genBusy)return;
  if(cfAccountVerdict()!=="ok"){toast("Sort out this device’s account data first");return;}
  var sel=state.selDate;
  var CTX=Object.assign({day:sel,reqId:"r"+Date.now()},cfNow());
  var ctxOk=function(){return cfCoachCtxValid(CTX,cfNow())&&cfAccountVerdict()==="ok";};
  var miss=dayMissing(sel);
  if(miss.length){toast("Log "+miss.join(", ")+" first to complete "+(sel===todayISO()?"today":"this day"));return;}
  state.nightBusy=true;render();
  var prevGen=(state.nightlyLog&&state.nightlyLog[sel]&&state.nightlyLog[sel].generated)||null;
  new Promise(function(res,rej){
    cloudGet(function(d,err){
      if(err){rej(new Error(err==="offline"?"No connection":"Couldn't reach your server"));return;}
      cfReconcile(d,"coach-preflight",function(decision,outcome){
        /* proceed ONLY on a genuinely completed safe state (finding 2) */
        if(!outcome.completed){rej(new Error(
          outcome.recoveryFailed?"Couldn’t save a safety copy — recap paused":
          outcome.conflict?"Changes in two places — resolve them first":
          outcome.pending?"Your newest changes are still on this device — recaps are paused until the sync fix ships":
          "Not ready to generate yet"));return;}
        if(!ctxOk()){rej(new Error("Account changed — recap cancelled"));return;}
        res();});});
  }).then(function(){
    return pushDataPromise();
  }).then(function(){
    if(!ctxOk())throw new Error("Account changed — recap cancelled");
    return new Promise(function(res,rej){
