  }catch(e){
    try{for(k in KEYS)localStorage.removeItem("cf:quarantine:"+stamp+":"+k);
        localStorage.removeItem("cf:quarantine:"+stamp+":manifest");}catch(e2){}
    toast("Couldn’t set that data aside safely — nothing was changed");return;}
