  for(k in KEYS){try{localStorage.removeItem(KEYS[k]);}catch(e){pendingKeys.push(k);}}
  try{localStorage.removeItem(REV_KEY);}catch(e){}
  if(pendingKeys.length){
    try{localStorage.setItem("cf:quarantine:"+stamp+":cleanupPending",JSON.stringify(pendingKeys));}catch(e){}
    toast("Data set aside and safely copied. Some old entries couldn’t be removed yet — they’ll be cleaned up automatically.");}
  location.reload();};

/* boot repair: finish pending cleanups — CONTENT-CONDITIONAL and stamp-isolated
   (Commit 1f). A pending job may delete a source key ONLY while its current
   value still byte-matches that stamp's own quarantined component; anything
   newer supersedes the job. One stamp can never touch another stamp's data
   or a value written after the set-aside. */
(function(){
  try{
    var KEYS={core:KEY,training:TKEY,workout:WOKEY};
    for(var i=localStorage.length-1;i>=0;i--){
      var k2=localStorage.key(i)||"";
      var m=/^cf:quarantine:(\d+):cleanupPending$/.exec(k2);
      if(!m)continue;
      var stamp=m[1];
      var pend=[];try{pend=JSON.parse(localStorage.getItem(k2))||[];}catch(e){}
      var left=[],superseded=[];
      pend.forEach(function(name){
        var srcKey=KEYS[name];if(!srcKey){superseded.push(name);return;}
        var cur=null;try{cur=localStorage.getItem(srcKey);}catch(e){left.push(name);return;}
        if(cur===null)return;                                   /* already clean */
        var quar=localStorage.getItem("cf:quarantine:"+stamp+":"+name);
        if(quar!==null&&cur===quar){                            /* exact match: safe to finish */
          try{localStorage.removeItem(srcKey);}catch(e){left.push(name);return;}
          if(localStorage.getItem(srcKey)!==null)left.push(name);
        }else superseded.push(name);                            /* newer data: NEVER deleted */
      });
      if(superseded.length)try{localStorage.setItem("cf:quarantine:"+stamp+":cleanupSuperseded",JSON.stringify(superseded));}catch(e){}
      if(left.length)localStorage.setItem(k2,JSON.stringify(left));
