/* ============================================================
   HARDENING — COMMIT 1f: Commit 1e re-review corrections
   (1) The revision/account guard applyCloudSafe gained in 1e is
   generalized to EVERY destructive operation — restore, import and
   logout-wipe all waited on an async safety copy and then acted without
   re-checking whether the device changed during the wait. (2) Quarantine
   boot cleanup is content-conditional (in-place fix earlier in this
   file): a pending job may only delete a value that still byte-matches
   its own stamp's quarantined component. Plus manifest/component
   integrity verification before commit and before export.
   ============================================================ */

/* @testable-start C1F */
/* One destructive-operation context for restore/import/logout (and the
   adoption guard from 1e). Captured before the async safety copy begins,
   re-verified immediately before the destructive commit. */
function cfCtxDrifted(a,b){
  return a.owner!==b.owner||a.gen!==b.gen||a.core!==b.core||a.training!==b.training||a.wo!==b.wo;}
/* Manifest integrity: parsed, right stamp, expected component set, and
   every component present with the recorded length. */
function cfManifestValid(man,stamp,comps){
  if(!man||typeof man!=="object")return false;
  if(String(man.stamp)!==String(stamp))return false;
  if(!Array.isArray(man.keys)||!man.keys.length)return false;
  for(var i=0;i<man.keys.length;i++){
    var k=man.keys[i];
    if(!(k in comps)||comps[k]===null)return false;
    if(man.sizes&&typeof man.sizes[k]==="number"&&man.sizes[k]!==comps[k].length)return false;}
  return true;}
/* @testable-end C1F */

function cfWorkoutFp(){try{var w=localStorage.getItem(WOKEY)||"";return w.length+":"+(w.slice(0,24));}catch(e){return "0:";}}
function cfDestructiveCtx(){return {owner:pbUid(),gen:CF_SESSION_GEN,core:revLocal("core"),training:revLocal("training"),wo:cfWorkoutFp()};}
function cfDestructiveStale(ctx){return cfCtxDrifted(ctx,cfDestructiveCtx());}

/* ---- restore: abort if the device changed while the safety copy was pending ---- */
recRestore=function(id,cb){
