/* ---- quarantine: verified manifest commit + content-conditional phase 3 ---- */
cfDisownLocal=function(){
  var stamp=String(Date.now());
  var KEYS={core:KEY,training:TKEY,workout:WOKEY};
  var src={},k;
  try{for(k in KEYS)src[k]=localStorage.getItem(KEYS[k])||"";}
  catch(e){toast("Couldn’t read this device’s data — nothing was changed");return;}
  /* Phase 1 — copy + verify */
  try{
    for(k in KEYS)localStorage.setItem("cf:quarantine:"+stamp+":"+k,src[k]);
    for(k in KEYS)if(localStorage.getItem("cf:quarantine:"+stamp+":"+k)!==src[k])throw new Error("verify "+k);
  }catch(e){
    try{for(k in KEYS)localStorage.removeItem("cf:quarantine:"+stamp+":"+k);}catch(e2){}
    toast("Couldn’t set that data aside safely — nothing was changed");return;}
  /* Phase 2 — manifest commit, READ BACK AND PARSED before it counts */
  var manifest={stamp:stamp,createdAt:Date.now(),appBuild:(typeof APP_BUILD!=="undefined"?APP_BUILD:""),
    keys:Object.keys(KEYS),sizes:{core:src.core.length,training:src.training.length,workout:src.workout.length}};
  try{
    localStorage.setItem("cf:quarantine:"+stamp+":manifest",JSON.stringify(manifest));
    var back=null;try{back=JSON.parse(localStorage.getItem("cf:quarantine:"+stamp+":manifest"));}catch(e){}
    if(!cfManifestValid(back,stamp,src))throw new Error("manifest verify");
    localStorage.setItem(CF_QUAR_FLAG,stamp);
  }catch(e){
    try{for(k in KEYS)localStorage.removeItem("cf:quarantine:"+stamp+":"+k);
        localStorage.removeItem("cf:quarantine:"+stamp+":manifest");}catch(e2){}
    toast("Couldn’t set that data aside safely — nothing was changed");return;}
  /* Phase 3 — content-conditional source cleanup; the recovery set is
     never rolled back from here on */
  var pendingKeys=[];
  for(k in KEYS){
    try{
      if(localStorage.getItem(KEYS[k])===src[k])localStorage.removeItem(KEYS[k]);
    }catch(e){pendingKeys.push(k);}}
  try{localStorage.removeItem(REV_KEY);}catch(e){}
  if(pendingKeys.length){
    try{localStorage.setItem("cf:quarantine:"+stamp+":cleanupPending",JSON.stringify(pendingKeys));}catch(e){}
    toast("Data set aside and safely copied. Some old entries couldn’t be removed yet — they’ll be cleaned up automatically.");}
  location.reload();};

/* export completeness now checks content lengths, not just key presence */
cfQuarComplete=function(stamp){
