/* ============================================================
   HARDENING — COMMIT 1g: Commit 1f re-review corrections
   (1) The workout "fingerprint" (length + first 24 chars) could miss
   ordinary same-length edits — the destructive context now carries the
   COMPLETE raw workout string and compares exactly, per the Architect's
   preferred option. (2) cfManifestValid now enforces the exact component
   set {core, training, workout} — no subsets, duplicates, unknown keys,
   or missing/invalid sizes — so an incomplete recovery set can never
   pass the phase-2 commit or the export gate.
   ============================================================ */

/* @testable-start C1G */
var CF_QUAR_COMPONENTS=["core","training","workout"];
function cfSameStringSet(actual,expected){
  if(!Array.isArray(actual)||actual.length!==expected.length)return false;
  var seen={},i;
  for(i=0;i<actual.length;i++){
    if(seen[actual[i]])return false;               /* duplicates */
    seen[actual[i]]=true;}
  for(i=0;i<expected.length;i++)if(!seen[expected[i]])return false;   /* missing */
  return true;}                                     /* same length + unique + all present ⇒ no unknowns */
function cfManifestValid(man,stamp,comps){
  if(!man||typeof man!=="object")return false;
  if(!comps||typeof comps!=="object")return false;
  if(String(man.stamp)!==String(stamp))return false;
  if(!cfSameStringSet(man.keys,CF_QUAR_COMPONENTS))return false;
  if(!man.sizes||typeof man.sizes!=="object")return false;
  if(!cfSameStringSet(Object.keys(man.sizes),CF_QUAR_COMPONENTS))return false;
  for(var i=0;i<CF_QUAR_COMPONENTS.length;i++){
    var k=CF_QUAR_COMPONENTS[i],sz=man.sizes[k];
    if(typeof sz!=="number"||sz<0||Math.floor(sz)!==sz)return false;
    if(typeof comps[k]!=="string")return false;     /* absent or non-string component */
    if(comps[k].length!==sz)return false;}
  return true;}
/* Cleanup decision as a pure step, so tests can prove PER-STAMP behavior
   (F4 test-quality improvement): which stamp was authorized to delete. */
function cfCleanupDecision(current,quarantined){
  if(current===null)return "clean";                 /* source already gone */
  if(quarantined!==null&&current===quarantined)return "delete";
  return "superseded";}
/* @testable-end C1G */

/* The COMPLETE raw workout value — null (absent) is distinct from "".
   A storage READ FAILURE is distinct from both: it marks the context invalid,
   so the destructive guard fails closed instead of mistaking an unreadable
   workout for an absent one (Architect hardening note 1). */
function cfWorkoutIdentity(){try{return {ok:true,value:localStorage.getItem(WOKEY)};}catch(e){return {ok:false,value:null};}}
cfDestructiveCtx=function(){var w=cfWorkoutIdentity();
  return {owner:pbUid(),gen:CF_SESSION_GEN,core:revLocal("core"),training:revLocal("training"),wo:w.value,woErr:!w.ok};};
cfDestructiveStale=function(ctx){var n=cfDestructiveCtx();
  if(ctx.woErr||n.woErr)return true;               /* unreadable ⇒ never proceed */
  return cfCtxDrifted(ctx,n);};
/* cfCtxDrifted compares .wo with !== — exact raw-string (or null) equality */

/* ============================================================
   Commit 1h — reopen vs in-flight recap (Architect .341 merge review)
   Reopening a day is an explicit instruction to delete that recap.
   A Coach request started before the reopen must never restore it.
   Mechanism: a per-day recap generation counter. The request context
   captures the generation at start; reopenDay() bumps it FIRST, so every
   existing ctxOk() checkpoint (before each poll, inside each callback,
   before the merge) sees a stale context and the late result is ignored.
   In-memory by design — a page reload aborts polling anyway.
   Ordinary athlete edits during a poll stay mergeable (1d behavior kept):
   the generation only moves on an explicit reopen of that same day.
   ============================================================ */
/* @testable-start C1H */
var CF_RECAP_GEN={};
function cfRecapGen(day){return CF_RECAP_GEN[day]||0;}
function cfRecapInvalidate(day){CF_RECAP_GEN[day]=cfRecapGen(day)+1;}
/* Coach context check, generation-aware: everything cfCoachCtxValid checks,
   plus the recap generation of the day the request was started for. */
function cfCoachCtxOk(ctx,now){
  return ctx.owner===now.owner&&ctx.gen===now.gen&&ctx.tok===now.tok&&
         ctx.recapGen===cfRecapGen(ctx.day);}
/* @testable-end C1H */

reopenDay=function(iso){
  cfRecapInvalidate(iso); /* FIRST: no in-flight Coach request outlives the intent */
  var lg=state.nightlyLog||{};if(lg[iso])delete lg[iso];state.nightlyLog=lg;
  var ns=state.nightlySummary;if(ns&&ns.date===iso)state.nightlySummary=null;
  if(state.settings&&state.settings.seenNightly===iso)state.settings.seenNightly=null;
  state.reopenAsk=null;save();render();toast("Day reopened");};

/* Final Coach Max binding: identical to the 1e flow, with the request context
   additionally carrying the per-day recap generation. */
genNightly=function(){
  if(!syncOn()){toast("Log in first");return;}
  if(state.nightBusy||state.genBusy)return;
  if(cfAccountVerdict()!=="ok"){toast("Sort out this device’s account data first");return;}
  var sel=state.selDate;
  var CTX=Object.assign({day:sel,reqId:"r"+Date.now(),recapGen:cfRecapGen(sel)},cfNow());
  var ctxOk=function(){return cfCoachCtxOk(CTX,cfNow())&&cfAccountVerdict()==="ok";};
  var miss=dayMissing(sel);
  if(miss.length){toast("Log "+miss.join(", ")+" first to complete "+(sel===todayISO()?"today":"this day"));return;}
  state.nightBusy=true;render();
  var prevGen=(state.nightlyLog&&state.nightlyLog[sel]&&state.nightlyLog[sel].generated)||null;
  new Promise(function(res,rej){
    cloudGet(function(d,err){
      if(err){rej(new Error(err==="offline"?"No connection":"Couldn't reach your server"));return;}
      cfReconcile(d,"coach-preflight",function(decision,outcome){
        if(!outcome.completed){rej(new Error(
          outcome.recoveryFailed?"Couldn’t save a safety copy — recap paused":
          outcome.conflict?"Changes in two places — resolve them first":
          outcome.pending?"Your newest changes are still on this device — recaps are paused until the sync fix ships":
          "Not ready to generate yet"));return;}
        if(!ctxOk()){rej(new Error("Account changed — recap cancelled"));return;}
        res();});});
  }).then(function(){
    return pushDataPromise();
  }).then(function(){
    if(!ctxOk())throw new Error("Account changed — recap cancelled");
    return new Promise(function(res,rej){
      pbSave({coachreq:{day:sel,ts:Date.now()}},function(ok){ok?res():rej(new Error("Couldn't reach your server"));});});
  }).then(function(){
    return new Promise(function(resolve){
      var n=0,MAX=70;
      function tick(){n++;
        if(!ctxOk()){resolve({aborted:true});return;}       /* before every poll */
        pbGetRecord(function(rec){
          if(!ctxOk()){resolve({aborted:true});return;}     /* inside every callback */
          var d=rec&&rec.data;
          var got=d&&d.nightlyLog&&d.nightlyLog[sel];
          if(got&&got.text&&got.generated!==prevGen){resolve({data:d});return;}
          if(n>=MAX){resolve({data:null});return;}
          setTimeout(tick,6000);});}
      setTimeout(tick,8000);});
  }).then(function(r){
    state.nightBusy=false;
    if(r&&r.aborted){render();return;}                      /* nothing merged, nothing shown */
    if(!ctxOk()){render();return;}                          /* before the merge */
    var d=r&&r.data;
    if(d){
      var merged=mergeCoachResultOnly(sel,d);
      state.settings.seenNightly=sel;saveLocal();
      if(!revIsDirty("core"))cfReconcile(d,"coach-result",function(){});
      state.nightOpen=true;
      toast(merged?((sel===todayISO()?"Today":"That day")+"’s recap is ready"):"Still working — it will appear here shortly");
    }else toast("Still working — it will appear here shortly");
    render();
  }).catch(function(e){state.nightBusy=false;render();toast(e.message||"Couldn’t generate");});};

/* ============================================================
   HARDENING — COMMIT 10: CAS CLIENT (decision core)

   Product Architect specification `features/commit10/spec/`, as amended by
   the pre-coding review. This block holds the PURE decisions; the wiring
   (scheduler, route adapter, conflict center, status surface) sits below it
   and calls into these.

   Why pure functions first: every guarantee this commit makes is a rule
   about WHEN something may happen — when a response may mark data clean,
   when a destructive choice may proceed, when a conflict may be resolved
   without asking. Rules that live inside network callbacks cannot be tested;
   these can, against the shipping source.
   ============================================================ */
/* @testable-start C10 */

/* ---- request identity and idempotency (spec §2.5, review §2) -------------
   The key is DERIVED, never stored: an identical retry after an unknown
   network outcome reproduces it, and any change to subsystem, expected
   revision or payload bytes produces a different one (CAS-08, CAS-09).
   The review requires a full collision-resistant digest — no truncation and
   no ad-hoc hash — so cfCasIdentity() builds the exact string to be hashed
   and cfCasKeyFrom() assembles the key from the full hex digest.
   Newline separators cannot occur inside a canonical JSON number or a
   subsystem name, so no two distinct identities can collide by framing. */
function cfCasIdentity(sub,expectedRev,canonPayload){
  return String(sub)+"\n"+String(expectedRev)+"\n"+String(canonPayload);}
function cfCasKeyFrom(hex){
  var k="c10-"+String(hex||"");
  return k.length<=96?k:null;}            /* null = refuse to send, never truncate */

/* ---- what a 200 may acknowledge (CAS-05, CAS-06) -------------------------
   A response may only clean the revision ITS OWN request captured. If the
   athlete edited while it was in flight, the newer state stays pending and
   is scheduled as the next coalesced commit. This is the defect Commit 1c
   fixed for the legacy path; the CAS path inherits the rule, not the code
   path. Returns the settled track plus whether work remains. */
function cfCasAck(track,sentRev,newServerRev){
  var success=Math.max(track.success||0,sentRev||0);
  var local=track.local||0;
  return {local:local,attempted:track.attempted||0,success:success,
          serverRev:(newServerRev===undefined||newServerRev===null)?track.serverRev:newServerRev,
          stillPending:local>success};}

/* ---- may this subsystem commit automatically? (CAS-11, spec §2.7) --------
   One list, consulted by the scheduler and by nothing else, so a new caller
   cannot accidentally bypass it. Ownership/auth gates from Commits 1c/1e are
   PRECONDITIONS here, not replacements. */
function cfCasCanCommit(st){
  if(!st)return false;
  if(st.conflictId)return false;                 /* unresolved conflict */
  if(st.blocked)return false;                    /* auth|update|oversize|invariant|recovery|ownership */
  return (st.local||0)>(st.success||0);}         /* something to send */

/* ---- automatic conflict resolution: exactly two cases (spec §1.4) --------
   A genuine content conflict is NEVER resolved automatically. The only
   silence permitted is when there is nothing to decide:
     "agree"      the server already holds what we tried to send
     "retry-once" the server moved but still matches our last agreed
                  baseline, so our payload is still the only new content
     "conflict"   everything else — ask the athlete
   Never newest-timestamp, never largest-payload, never prefer-server,
   never prefer-device, never merge, never retry until one side wins. */
function cfCasAutoResolve(serverCanon,sentCanon,baselineCanon,retriedAlready){
  if(serverCanon===sentCanon)return "agree";
  if(!retriedAlready&&baselineCanon&&serverCanon===baselineCanon)return "retry-once";
  return "conflict";}

/* ---- the destructive-resolution context (review §3) ---------------------
   Commit 1f's cfCtxDrifted predicate is proven and reused, but its whole-app
   context is deliberately NOT: under it, editing Training would abort an
   in-progress Health & progress adoption. A CAS resolution is about ONE
   subsystem, so the context names that subsystem and carries only what makes
   THIS decision stale. C10-PLAN-05/06 are the pair that prove it: same
   interruption, opposite outcomes, decided solely by which subsystem moved. */
function cfCasCtx(sub,owner,gen,subLocalRev,conflictId,capturedServerRev,recRef){
  return {sub:sub,owner:owner,gen:gen,rev:subLocalRev,
          conflictId:conflictId,serverRev:capturedServerRev,rec:recRef};}
function cfCasCtxDrifted(a,b){
  if(!a||!b)return true;
  return a.sub!==b.sub||a.owner!==b.owner||a.gen!==b.gen||a.rev!==b.rev||
         a.conflictId!==b.conflictId||a.serverRev!==b.serverRev||a.rec!==b.rec;}

/* ---- the cas-conflict recovery artifact (review §1) ---------------------
   The existing recovery format stores a whole-snapshot {core,training,workout}
   set. A CAS conflict concerns ONE subsystem, so reusing that format would
   pair a genuine server `core` payload with a local `training` payload the
   server never held — the "misleading hybrid snapshot" the review forbids.
   Hence a second artifact kind with its own exact-set rule. cfManifestValid
   (Commit 1g) keeps governing set-aside artifacts, untouched.
   The artifact must be self-contained enough to restore its subsystem: kind,
   subsystem, server revision, canonical hash, byte length, account. */
/* UTF-8 BYTES, never String.length. Review correction C10-P1-01: .length
   counts UTF-16 code units, so "81.5 kg — féé" measures short and a payload
   could validate against the wrong size. The server measures bytes and so does
   the recovery contract. Written out longhand rather than via TextEncoder so it
   is pure and testable in the same sandbox as everything else here.
   The same trap appeared during the production cutover, where sqlite length()
   reported 19,030 characters for a payload of 19,556 UTF-8 bytes. */
function cfCasUtf8Bytes(s){
  s=String(s===undefined||s===null?"":s);
  var n=0;
  for(var i=0;i<s.length;i++){
    var c=s.charCodeAt(i);
    if(c<0x80){n+=1;}
    else if(c<0x800){n+=2;}
    else if(c>=0xD800&&c<=0xDBFF){                      /* high surrogate */
      var d=(i+1<s.length)?s.charCodeAt(i+1):0;
      if(d>=0xDC00&&d<=0xDFFF){n+=4;i++;}               /* valid pair -> 4 bytes */
      else{n+=3;}                                      /* lone surrogate -> U+FFFD */
    }
    else{n+=3;}}
  return n;}

/* A declared digest must LOOK like a full SHA-256 before it is trusted enough
   to compare (review C10-P1-02). */
function cfCasHashValid(hex){return typeof hex==="string"&&/^[0-9a-f]{64}$/.test(hex);}

/* SHAPE only: the artifact is well-formed. This is not the same as verified —
   see cfCasRecVerified. Kept separate so the pure shape rules stay testable
   without a digest implementation in the sandbox. */
function cfCasRecValid(man,id,comps){
  if(!man||typeof man!=="object")return false;
  if(man.kind!=="cas-conflict")return false;
  if(String(man.id)!==String(id))return false;
  if(man.sub!=="core"&&man.sub!=="training")return false;
  if(typeof man.serverRev!=="number"||man.serverRev<0||Math.floor(man.serverRev)!==man.serverRev)return false;
  if(!man.account)return false;
  if(!Array.isArray(man.keys)||man.keys.length!==1||man.keys[0]!=="payload")return false;
  if(!comps||typeof comps.payload!=="string")return false;
  if(!man.sizes||typeof man.sizes.payload!=="number")return false;
  if(man.sizes.payload!==cfCasUtf8Bytes(comps.payload))return false;   /* BYTES */
  if(Object.keys(comps).length!==1)return false;              /* no extra components */
  if(!cfCasHashValid(man.hash))return false;
  return true;}

/* VERIFIED: shape, plus proof that the stored bytes really are what the
   manifest claims and that the artifact belongs to this account and this
   conflict (review C10-P1-02). "Verified" must mean checked, not declared.
   The digest is computed by the caller (crypto.subtle) and passed in, so this
   stays pure and the tests can hash with a real SHA-256 implementation.
   A conflict card must not become actionable until this returns true. */
function cfCasRecVerified(man,id,comps,expected,computedHashHex){
  if(!cfCasRecValid(man,id,comps))return false;
  if(!expected)return false;
  if(!cfCasHashValid(computedHashHex))return false;
  if(computedHashHex!==man.hash)return false;                 /* content really matches */
  if(man.account!==expected.account)return false;             /* belongs to THIS account */
  if(man.sub!==expected.sub)return false;                     /* and this subsystem */
  if(man.serverRev!==expected.serverRev)return false;         /* and this conflict's revision */
  if(String(man.id)!==String(expected.rec))return false;      /* and the referenced artifact */
  return true;}

/* An artifact is immutable once a conflict references it: a fresh capture
   writes a NEW id. Anything else would let the copy the athlete is deciding
   against change under them. */
function cfCasRecMayWrite(existingManifest){return !existingManifest;}

/* ---- first-row creation needs positive proof (review §4C) ---------------
   Absent local revision metadata is NOT evidence that the account has no row.
   All four must be positively established by an authenticated bootstrap. */
function cfCasFirstRowAllowed(proof){
  return !!proof&&proof.authenticated===true&&proof.serverRowAbsent===true&&
         proof.ownershipResolved===true&&proof.everAcknowledgedRow===false&&
         proof.localDataBelongsToAccount===true;}

/* ---- compact status priority (spec §3.1) --------------------------------
   One indicator across both subsystems, highest-priority state wins. */
var CF_CAS_STATUS_ORDER=["update","conflict","auth","failed","pending","syncing","synced"];
function cfCasStatus(a,b){
  for(var i=0;i<CF_CAS_STATUS_ORDER.length;i++){
    var s=CF_CAS_STATUS_ORDER[i];
    if(a===s||b===s)return s;}
  return "synced";}

/* ---- bounded retry (spec §2.6, CAS-20) ---------------------------------
   500/network only. Everything else is handled by its own status rule and
   must never enter this loop. Returns the delay in ms, or null to stop. */
function cfCasRetryDelay(status,attempt){
  if(!(status===0||status>=500))return null;   /* 0 = network failure */
  if(attempt===0)return 5000;
  if(attempt===1)return 30000;
  return null;}                                 /* stop; wait for an explicit trigger */

/* ---- response contracts (review C10-P8-05) ------------------------------
   A status is never proof. These say what a valid success and a valid conflict
   actually look like, so a malformed body cannot be canonicalized into a fake
   conflict or a fake recovery artifact. */
function cfCasNonNegInt(v){return typeof v==="number"&&isFinite(v)&&v>=0&&Math.floor(v)===v;}
function cfCasOkBody(body,sub){
  if(!body||body.ok!==true)return false;
  if(body.subsystem!==sub)return false;          /* absent is not valid either */
  return cfCasNonNegInt(body.newRev);}
function cfCasConflictBody(body,sub){
  if(!body||body.conflict!==true)return false;
  if(body.subsystem!==undefined&&body.subsystem!==sub)return false;
  if(body.serverRev===null)return body.payload===null;      /* documented no-row case */
  if(!cfCasNonNegInt(body.serverRev))return false;
  return !!body.payload&&typeof body.payload==="object"&&!Array.isArray(body.payload);}

/* ---- per-status disposition (spec §4) ----------------------------------
   The single table that decides what a response means. "invariant" is the
   reused-key case: a client bug the athlete cannot act on, so it must reach
   the safe failure state and never the conflict center. */
function cfCasDisposition(status,body,sub){
  /* A 200 is not success on its own. The route's success contract is
     {ok:true, subsystem, newRev}; anything else answering 200 — a proxy page, a
     misrouted request, a framework body — must never be read as "committed",
     because the client would mark the athlete's data clean and stop syncing it.
     This is the Round 2 rule applied to the client: never assert on a status
     alone. Caught by the c1d/c1h suites, which expect an edit to stay pending
     and saw it go clean against a generic 200 stub. */
  if(status===200)return cfCasOkBody(body,sub)?"ok":"contract";
  if(status===409){
    if(body&&body.conflict===true)return cfCasConflictBody(body,sub)?"conflict":"contract";
    return "invariant";}                        /* key reused with a different request */
  if(status===401||status===403)return "auth";
  if(status===426)return "update";
  if(status===413)return "oversize";
  if(status===400)return "contract";
  if(status===0||status>=500)return "retry";
  return "contract";}
/* @testable-end C10 */

/* ---- CAS recovery artifact: storage integration -------------------------
   The pure contract above says what a valid artifact IS. This says how one
   comes into existence, and the order is the whole point (Architect progress-2
   review, "recovery immutability boundary"):

     1. choose a FRESH id
     2. refuse an existing id BEFORE writing anything
     3. write the payload bytes first
     4. READ THEM BACK and hash what came back, never what we meant to write
     5. write the manifest LAST — its presence is what makes the artifact real
     6. on any failure, leave nothing actionable behind
     7. no later caller can overwrite it in place

   Step 4 is not ceremony. A digest computed from the in-memory string would
   certify our intention; a digest computed from the bytes storage handed back
   certifies what a future reader will actually find. Quota truncation, a
   storage shim that mangles unicode, or a partial write are all invisible to
   the first and caught by the second. */
/* ---- CAS recovery artifact: storage integration -------------------------
   Rebuilt for the progress-4 review. Three things changed and each closes a
   defect the previous version only appeared to handle:

   1. PUBLICATION IS SERIALISED BY A REAL EXCLUSIVE LOCK. The previous version
      used a localStorage claim written and re-read. localStorage has no atomic
      compare-and-set, so two tabs can both see an empty claim, both write, and
      both believe they own it at different instants — and my "concurrent" test
      never demonstrated otherwise, because it awaited the first writer before
      starting the second. That is sequential contention wearing a concurrency
      label. Web Locks now provide the exclusion; the claim token remains only
      as an ownership marker for cleanup.
      With no Web Locks available the write FAILS CLOSED. It does not quietly
      fall back to the claim as though that were equivalent.

   2. THE OPERATION CONTEXT IS CAPTURED AND RE-VERIFIED. crypto.subtle.digest
      is asynchronous, and an account can switch while it is pending. Cleanup
      previously resolved keys from the LIVE session, so a failure after a
      switch could address the new account's namespace and leave the old one
      littered. Every attempt now captures owner, session generation, keys,
      lock name and token up front, and every continuation checks for drift
      before publishing.

   3. THE NAMESPACE IS NOT CALLER-SELECTABLE. Key construction is private to
      this module; callers pass an artifact id and nothing else, so no ordinary
      caller can address another account's namespace by asking for it.
      (Application-level isolation — not a claim that same-origin script or
      devtools are cryptographically fenced out.) */
var cfCasRecStore=(function(){
  var PREFIX="cf:casrec:";

  function scopeNow(){var u=pbUid();return u?String(u):"";}
  function genNow(){return (typeof CF_SESSION_GEN==="undefined")?0:CF_SESSION_GEN;}
  function keysFor(scope,id){
    var base=PREFIX+scope+":"+id;   /* callers validate; see purgeScoped/validId */
    return {claim:base+":claim",payload:base+":payload",manifest:base+":manifest"};}

  function randomHex(bytes){
    try{
      if(typeof crypto!=="undefined"&&crypto.getRandomValues){
        var v=new Uint8Array(bytes||16);crypto.getRandomValues(v);
        var h="";for(var i=0;i<v.length;i++){var x=v[i].toString(16);h+=(x.length===1?"0":"")+x;}
        return h;}
    }catch(e){}
    return null;}                                        /* no entropy: refuse, never fake it */

  function newId(sub){
    var r=null;
    try{if(typeof crypto!=="undefined"&&crypto.randomUUID)r=String(crypto.randomUUID()).replace(/-/g,"");}catch(e){}
    if(!r)r=randomHex(16);
    if(!r)return null;
    return "casrec-"+sub+"-"+r;}

  /* Immutable per-attempt context. Nothing downstream reads the live session. */
  function capture(id){
    var scope=scopeNow();
    return {owner:scope,gen:genNow(),id:id,keys:scope?keysFor(scope,id):null,
            lock:"cf-cas-recovery:"+scope+":"+id,token:randomHex(8)};}
  function drifted(ctx){return ctx.owner!==scopeNow()||ctx.gen!==genNow();}

  function sha256Hex(str,cb){
    try{
      if(typeof crypto==="undefined"||!crypto.subtle){cb(null);return;}
      var bytes=new TextEncoder().encode(String(str));
      crypto.subtle.digest("SHA-256",bytes).then(function(buf){
        var v=new Uint8Array(buf),h="";
        for(var i=0;i<v.length;i++){var x=v[i].toString(16);h+=(x.length===1?"0":"")+x;}
        cb(h);},function(){cb(null);});
    }catch(e){cb(null);}}

  /* Cleanup against the CAPTURED keys, never the live session's, and only when
     the claim still carries our token. A loser removes its own mess and
     nothing else.
     CONTRACT: callers must already hold this artifact's lock. Re-acquiring it
     here would deadlock against the writer that is calling us. */
  function purgeCapturedLocked(ctx){
    if(!ctx||!ctx.keys)return false;
    try{
      if(localStorage.getItem(ctx.keys.claim)!==ctx.token)return false;
      var had=localStorage.getItem(ctx.keys.manifest)!==null||
              localStorage.getItem(ctx.keys.payload)!==null||
              localStorage.getItem(ctx.keys.claim)!==null;
      localStorage.removeItem(ctx.keys.manifest);
      localStorage.removeItem(ctx.keys.payload);
      localStorage.removeItem(ctx.keys.claim);
      return had;
    }catch(e){return false;}}

  /* Locked deletion for an explicit captured scope. Private: reachable only
     through a capability handed to the writer that created the artifact. */
  function purgeScoped(scope,id,cb){
    if(!scope){cb(false,"unauthenticated");return;}
    if(!validId(id)){cb(false,"invalid-id");return;}   /* never key off an unvalidated id */
    var lock="cf-cas-recovery:"+scope+":"+id;
    withLock(lock,function(release){
      var K=keysFor(scope,id),had=false,gone=false;
      try{
        had=localStorage.getItem(K.manifest)!==null||localStorage.getItem(K.payload)!==null||
            localStorage.getItem(K.claim)!==null;
        localStorage.removeItem(K.manifest);
        localStorage.removeItem(K.payload);
        localStorage.removeItem(K.claim);
        /* Report what is GONE, not what was there. Deriving "removed" from what
           existed before the call meant a storage layer that silently ignored
           removeItem — quota state, a wrapper, an extension — was reported as a
           successful deletion, and the pending-cleanup ledger then had nothing
           to retry. Found by the C10-P13 ledger test. */
        gone=localStorage.getItem(K.manifest)===null&&localStorage.getItem(K.payload)===null&&
             localStorage.getItem(K.claim)===null;
      }catch(e){release();cb(false,"storage");return;}
      release();
      if(!gone){cb(false,"not-removed");return;}
      cb(had,had?null:"absent");
    },function(){cb(false,"no-lock");});}

  /* Pending-cleanup ledger (review C10-P13-01). A purge that fails must not be
     silently forgotten: reporting "replaced" while an old verified copy of the
     athlete's data survives is exactly the kind of quiet accumulation this
     project keeps finding. Failed deletions are recorded per account and
     retried; the ledger holds artifact IDs only, never payloads. */
  var PENDING_MAX=200;
  /* ONE strict artifact-id contract, matching exactly what newId produces:
     crypto.randomUUID with dashes stripped, or 16 random bytes — both 32 hex
     characters. A loose pattern let arbitrary strings ("not-an-artifact",
     "../../other-key", "casrec-core-") survive a ledger read and then be used
     to build storage keys. No cleanup path may construct a key from an
     unvalidated id (review C10-P15-02). */
  var ID_RE=/^casrec-(core|training)-[0-9a-f]{32}$/;
  function validId(id){return typeof id==="string"&&ID_RE.test(id);}
  function pendingKey(scope){return PREFIX+scope+":pending-cleanup";}
  function pendingLock(scope){return "cf-cas-recovery-cleanup:"+scope;}
  function pendingList(scope){
    try{var raw=localStorage.getItem(pendingKey(scope));var a=raw?JSON.parse(raw):[];
        /* Invalid persisted entries are ignored entirely: they are not
           obligations, and they must not consume capacity. */
        return Array.isArray(a)?a.filter(validId):[];}
    catch(e){return [];}}

  /* EVERY ledger mutation runs under one exclusive account-level lock, re-reads
     the current list inside it, merges, writes, and READS BACK to confirm.

     The previous version did a bare read-modify-write, so two tabs recording
     different failed deletions would each write their own list and the last
     writer would erase the other's obligation — recreating, inside the ledger,
     precisely the untracked-artifact defect the ledger exists to prevent
     (review C10-P14-01). It also truncated at 200 silently, which loses an
     obligation for the same reason with no race required (C10-P14-02).

     mutate(list) returns the new list, or null to abort. cb(ok, reason). */
  function pendingMutate(scope,mutate,cb){
    cb=cb||function(){};
    if(!scope){cb(false,"unauthenticated");return;}
    withLock(pendingLock(scope),function(release){
      var current=pendingList(scope),next=null;
      try{next=mutate(current.slice());}catch(e){next=null;}
      if(next===null){release();cb(false,"aborted");return;}
      if(next.length>PENDING_MAX){release();cb(false,"ledger-full");return;}  /* never truncate */
      var serialized=next.length?JSON.stringify(next):"";
      try{
        if(!next.length)localStorage.removeItem(pendingKey(scope));
        else localStorage.setItem(pendingKey(scope),serialized);
      }catch(e){release();cb(false,"storage");return;}
      /* Read back: a write that did not persist must not be reported as
         recorded, or the obligation is lost exactly as if it were truncated. */
      var back=null;
      try{back=localStorage.getItem(pendingKey(scope));}catch(e){back=null;}
      var ok=next.length?(back===serialized):(back===null);
      release();
      cb(ok,ok?null:"not-persisted");
    },function(){cb(false,"no-lock");});}     /* no lock: say so, never pretend */

  function pendingAdd(scope,id,cb){
    cb=cb||function(){};
    if(!validId(id)){cb(false,"invalid-id");return;}
    pendingMutate(scope,function(list){
      if(list.indexOf(id)>=0)return list;             /* already owed */
      return list.concat([id]);},cb);}                /* mutate() enforces the bound */
  function pendingDrop(scope,id,cb){
    cb=cb||function(){};
    if(!validId(id)){cb(false,"invalid-id");return;}
    pendingMutate(scope,function(list){
      return list.filter(function(x){return x!==id;});},cb);}

  function withLock(name,body,unavailable){
    try{
      if(typeof navigator==="undefined"||!navigator.locks||!navigator.locks.request){unavailable();return;}
      navigator.locks.request(name,{mode:"exclusive"},function(){
        return new Promise(function(release){body(release);});
      }).catch(function(){unavailable();});
    }catch(e){unavailable();}}

  /* Everything inside here runs holding the exclusive lock for this artifact. */
  function writeLocked(ctx,sub,serverRev,payloadStr,done){
    var K=ctx.keys,man0=null,pay0=null;
    try{man0=localStorage.getItem(K.manifest);pay0=localStorage.getItem(K.payload);}
    catch(e){done(false,"storage");return;}
    if(!cfCasRecMayWrite(man0)){done(false,"exists");return;}
    if(pay0!==null){done(false,"exists");return;}
    try{localStorage.setItem(K.claim,ctx.token);}catch(e){done(false,"storage");return;}
    var want=String(payloadStr);
    try{localStorage.setItem(K.payload,want);}catch(e){purgeCapturedLocked(ctx);done(false,"storage");return;}
    var back=null;
    try{back=localStorage.getItem(K.payload);}catch(e){back=null;}
    if(back===null||back!==want){purgeCapturedLocked(ctx);done(false,"readback");return;}
    sha256Hex(back,function(hex){
      /* The digest was asynchronous: the account may have changed underneath. */
      if(drifted(ctx)){purgeCapturedLocked(ctx);done(false,"drift");return;}
      if(!cfCasHashValid(hex)){purgeCapturedLocked(ctx);done(false,"digest");return;}

      /* TWO-PHASE PUBLICATION (review C10-P6-01). The canonical manifest is the
         publication boundary, so it must not exist until the artifact is
         verified. Writing it earlier — as the previous version did, before the
         final digest — left a window in which another context could read the
         manifest and payload, verify them, and treat the artifact as actionable
         while this writer was still deciding whether it had succeeded. If that
         writer then drifted or failed, it purged an artifact a conflict layer
         had already been handed.

         The candidate therefore stays IN MEMORY and is verified against the
         stored payload first. No provisional key is written at all, so there is
         no provisional state for a public reader to trip over. */
      var candidate={kind:"cas-conflict",id:String(ctx.id),sub:sub,serverRev:serverRev,account:ctx.owner,
                     keys:["payload"],sizes:{payload:cfCasUtf8Bytes(back)},hash:hex};
      if(!cfCasRecValid(candidate,ctx.id,{payload:back})){purgeCapturedLocked(ctx);done(false,"invalid");return;}
      /* Re-read the payload after hashing and confirm it has not moved, so the
         bytes we verified are the bytes on disk. */
      var payAgain=null;
      try{payAgain=localStorage.getItem(K.payload);}catch(e){payAgain=null;}
      if(payAgain===null){purgeCapturedLocked(ctx);done(false,"final-missing");return;}
      if(payAgain!==back){purgeCapturedLocked(ctx);done(false,"final-moved");return;}
      var expect={account:ctx.owner,sub:sub,serverRev:serverRev,rec:ctx.id};
      if(!cfCasRecVerified(candidate,ctx.id,{payload:payAgain},expect,hex)){
        purgeCapturedLocked(ctx);done(false,"final-unverified");return;}

      /* Verified. NOW publish — the canonical manifest is written last and is
         the only thing public read/list recognise. */
      var serialized=JSON.stringify(candidate);
      try{localStorage.setItem(K.manifest,serialized);}
      catch(e){purgeCapturedLocked(ctx);done(false,"storage");return;}
      /* localStorage writes are synchronous and we still hold the lock, so a
         read-back here is sufficient to confirm what was actually published. */
      var stored=null;
      try{stored=localStorage.getItem(K.manifest);}catch(e){stored=null;}
      if(stored!==serialized){purgeCapturedLocked(ctx);done(false,"publish-mismatch");return;}
      /* A capability to remove THIS artifact under the scope it was written in.
         Handed only to the caller that created it, so a failed or drifted
         operation can clean up its own artifact without the public purge, which
         always addresses the currently authenticated account. */
      var cap={purge:function(cb){purgeScoped(ctx.owner,ctx.id,cb||function(){});}};
      done(true,candidate,cap);});}

  return {
    newId:newId,
    /* cb(ok, manifestOrReason). No account argument: the namespace comes from
       the authenticated session at capture time. */
    write:function(id,sub,serverRev,payloadStr,cb){
      var ctx=capture(id);
      if(!ctx.owner){cb(false,"unauthenticated");return;}
      if(!ctx.token){cb(false,"entropy");return;}
      withLock(ctx.lock,function(release){
        /* Forward ALL THREE arguments. The third is the captured-owner purge
           capability, and dropping it here made the scheduler's drift cleanup
           unreachable: cap was always undefined, so a verified artifact could be
           orphaned and no test noticed, because the test exercised the store's
           own owner/generation drift check instead — which fires BEFORE
           publication and never produces a capability at all. */
        writeLocked(ctx,sub,serverRev,payloadStr,function(ok,out,cap){release();cb(ok,out,cap);});
      },function(){cb(false,"no-lock");});},        /* fail closed, never claim-only */

    read:function(id,expected,cb){
      var ctx=capture(id);
      if(!ctx.owner){cb(null,"unauthenticated");return;}
      var K=ctx.keys,raw=null,pay=null;
      try{raw=localStorage.getItem(K.manifest);pay=localStorage.getItem(K.payload);}
      catch(e){cb(null,"storage");return;}
      if(raw===null){cb(null,"absent");return;}
      if(pay===null){cb(null,"missing-payload");return;}
      var man=null;try{man=JSON.parse(raw);}catch(e){cb(null,"unparseable");return;}
      sha256Hex(pay,function(hex){
        if(drifted(ctx)){cb(null,"drift");return;}
        if(!cfCasRecVerified(man,ctx.id,{payload:pay},expected,hex)){cb(null,"unverified");return;}
        cb(pay,null);});},

    /* Only the current account's artifacts are addressable or listable. */
    list:function(){
      var sc=scopeNow(),out=[];
      if(!sc)return out;
      var pre=PREFIX+sc+":";
      try{
        for(var i=0;i<localStorage.length;i++){
          var k=localStorage.key(i)||"";
          if(k.indexOf(pre)!==0)continue;
          var rest=k.slice(pre.length),cut=rest.lastIndexOf(":");
          if(cut>0&&rest.slice(cut+1)==="manifest")out.push(rest.slice(0,cut));}
      }catch(e){}
      return out;},

    /* Public purge. ASYNCHRONOUS AND LOCKED (review C10-P5-01): deletion mutates
       the same keys a writer publishes, so it must take the same exclusive lock.
       Without it this interleaving was possible — writer takes the lock, writes
       and reads back the payload, waits on the digest; purge deletes the payload
       unlocked; the writer publishes its manifest and reports SUCCESS. The
       artifact then has a manifest and no payload, and a conflict layer has been
       told a recovery copy exists that does not.

       A synchronous boolean cannot honestly represent completion of a
       cross-context locked operation, so this returns via callback:
         cb(removed, reason) — removed is what was ACTUALLY removed.
       Without Web Locks it refuses rather than pretending deletion happened. */
    purge:function(id,cb){
      cb=cb||function(){};
      var sc=scopeNow();
      if(!sc){cb(false,"unauthenticated");return;}
      var lock="cf-cas-recovery:"+sc+":"+id;
      withLock(lock,function(release){
        /* Re-evaluate the owner inside the lock: it may have changed while we
           queued behind a writer. */
        var scNow=scopeNow();
        if(scNow!==sc){release();cb(false,"drift");return;}
        var K=keysFor(scNow,id),removed=false;
        try{
          var hadMan=localStorage.getItem(K.manifest)!==null;
          var hadPay=localStorage.getItem(K.payload)!==null;
          var hadClaim=localStorage.getItem(K.claim)!==null;
          /* same honesty rule as purgeScoped: verify absence after removing */
          /* Manifest FIRST: the artifact stops being actionable the instant it
             goes, so a crash mid-purge leaves something inert, not something
             half-usable. */
          localStorage.removeItem(K.manifest);
          localStorage.removeItem(K.payload);
          localStorage.removeItem(K.claim);
          var stillThere=localStorage.getItem(K.manifest)!==null||
                         localStorage.getItem(K.payload)!==null||
                         localStorage.getItem(K.claim)!==null;
          if(stillThere){release();cb(false,"not-removed");return;}
          removed=hadMan||hadPay||hadClaim;
        }catch(e){release();cb(false,"storage");return;}
        release();cb(removed,removed?null:"absent");
      },function(){cb(false,"no-lock");});},

    scope:scopeNow,
    sha256:sha256Hex,

    /* Delete an artifact for a CAPTURED scope and report honestly. A failure is
       recorded for retry rather than swallowed. */
    purgeTracked:function(scope,id,cb){
      cb=cb||function(){};
      if(!scope){cb(false,"unauthenticated");return;}
      /* An unusable id is not an untracked OBLIGATION — there is nothing to
         delete and nothing to owe. Reporting "untracked:" here would describe
         a cleanup debt that does not exist. */
      if(!validId(id)){cb(false,"invalid-id");return;}
      purgeScoped(scope,id,function(removed,why){
        if(removed||why==="absent"){
          pendingDrop(scope,id,function(){cb(true,removed?null:"absent");});
          return;}
        /* The deletion failed. Whether the OBLIGATION was recorded is a second,
           separately reportable fact — "we could not delete it and we could not
           even write that down" is a different situation from "we will retry". */
        pendingAdd(scope,id,function(recorded,rwhy){
          cb(false,recorded?(why||"failed"):("untracked:"+(rwhy||"failed")));});});},

    /* Retry every deletion this account still owes. Never touches another
       account's ledger, because the scope comes from the live session. */
    cleanupSweep:function(cb){
      cb=cb||function(){};
      var scope=scopeNow();
      if(!scope){cb(0);return;}
      var ids=pendingList(scope),done=0,left=ids.length;
      if(!left){cb(0);return;}
      ids.forEach(function(id){
        purgeScoped(scope,id,function(removed,why){
          if(!(removed||why==="absent")){if(--left===0)cb(done);return;}
          /* Only drop the obligation once the artifact is verifiably gone. */
          pendingDrop(scope,id,function(dropped){
            if(dropped)done++;
            if(--left===0)cb(done);});});});},

    pending:function(){return pendingList(scopeNow());},

    /* Deterministic account-scoped inventory. If a ledger write ever fails, the
       artifact is still discoverable: it is a manifest in this account's
       namespace that no live reference and no ledger entry accounts for. This
       is the recovery path the review requires for a capacity or persistence
       failure — nothing depends on the ledger having succeeded. */
    reconcile:function(activeIds,cb){
      cb=cb||function(){};
      var scope=scopeNow();
      if(!scope){cb([],"unauthenticated");return;}
      var owed=pendingList(scope),live=activeIds||[];
      var pre=PREFIX+scope+":",orphans=[];
      try{
        for(var i=0;i<localStorage.length;i++){
          var k=localStorage.key(i)||"";
          if(k.indexOf(pre)!==0)continue;
          var rest=k.slice(pre.length),cut=rest.lastIndexOf(":");
          if(cut<0||rest.slice(cut+1)!=="manifest")continue;
          var id=rest.slice(0,cut);
          if(!validId(id))continue;                    /* only real artifact ids */
          if(live.indexOf(id)>=0)continue;
          if(owed.indexOf(id)>=0)continue;
          orphans.push(id);}
      }catch(e){cb([],"storage");return;}
      cb(orphans,null);}
  };
})();

/* Thin named wrappers — the call surface the rest of Commit 10 uses. */
function cfCasRecNewId(sub){return cfCasRecStore.newId(sub);}
function cfCasRecWrite(id,sub,serverRev,payloadStr,cb){return cfCasRecStore.write(id,sub,serverRev,payloadStr,cb);}
function cfCasRecRead(id,expected,cb){return cfCasRecStore.read(id,expected,cb);}
function cfCasRecList(){return cfCasRecStore.list();}
function cfCasRecPurge(id,cb){return cfCasRecStore.purge(id,cb);}
function cfCasRecScope(){return cfCasRecStore.scope();}
function cfCasRecPurgeTracked(scope,id,cb){return cfCasRecStore.purgeTracked(scope,id,cb);}
function cfCasRecCleanupSweep(cb){return cfCasRecStore.cleanupSweep(cb);}
function cfCasRecPendingCleanup(){return cfCasRecStore.pending();}
function cfCasRecReconcile(cb){
  var live=[];
  var a=cfCasConflictId("core"),b=cfCasConflictId("training");
  if(a)live.push(a); if(b)live.push(b);
  return cfCasRecStore.reconcile(live,cb);}
/* The adapter needs the same digest the store uses; it lives in the closure so
   there is one implementation, not two. */
function cfCasSha256Hex(str,cb){return cfCasRecStore.sha256(str,cb);}

/* ---- CAS scheduler and route adapter ------------------------------------
   This is where the rules above become network behaviour. Commit 1b froze the
   raw snapshot write path and left scheduleCloudPush/scheduleTrainingPush
   bumping a revision and nothing more. Commit 10 re-points those same entry
   points at the commit route — it does not reopen the frozen path, and
   C10-PLAN-12 asserts that no legacy scheduler survives alongside this one. */
var CF_CAS_DEBOUNCE_MS=3000;                       /* spec §2.1 */
var CF_CAS_TIMER={core:null,training:null};
var CF_CAS_OP={core:null,training:null};           /* the ONE active operation */
/* A queued rerun records WHOSE trigger it was. A bare boolean let an Account A
   trigger survive a logout and schedule a run that captured Account B's live
   state — queued work must not cross an ownership boundary (review C10-P9-01). */
var CF_CAS_RERUN={core:null,training:null};
var CF_CAS_SEQ={core:{retried:false},training:{retried:false}};  /* conflict sequence */
/* Which operation set the current transient block. A late callback may clear
   only the state IT created — a string equality check on "preserving" cannot
   tell an old operation's pause from a newer one's (review C10-P10-02). */
var CF_CAS_BLOCK_OP={core:null,training:null};
function cfCasSetBlock(sub,kind,opToken){CF_CAS_BLOCK[sub]=kind;CF_CAS_BLOCK_OP[sub]=kind?(opToken||null):null;}
function cfCasOwnsBlock(sub,opToken){return CF_CAS_BLOCK_OP[sub]!==null&&CF_CAS_BLOCK_OP[sub]===opToken;}
var CF_CAS_ATTEMPT={core:0,training:0};
var CF_CAS_BLOCK={core:null,training:null};

/* Persisted alongside the existing revision track so a reload does not lose
   what the server last told us. */
function cfCasMapGet(name,sub){try{var a=revAll();var m=a[name]||{};return m[sub];}catch(e){return undefined;}}
function cfCasMapSet(name,sub,v){try{var a=revAll();a[name]=a[name]||{};a[name][sub]=v;revSaveAll(a);}catch(e){}}
function cfCasServerRev(sub){var v=cfCasMapGet("casServerRev",sub);return typeof v==="number"?v:0;}
function cfCasSetServerRev(sub,n){cfCasMapSet("casServerRev",sub,n);}
function cfCasBaseline(sub){return cfCasMapGet("casBaseline",sub)||"";}
function cfCasSetBaseline(sub,c){cfCasMapSet("casBaseline",sub,c||"");}
function cfCasConflictId(sub){return cfCasMapGet("casConflict",sub)||null;}
function cfCasSetConflictId(sub,id){cfCasMapSet("casConflict",sub,id||null);}

/* The snapshot each subsystem owns. Deliberately the same two fields the
   legacy path sent, so nothing new becomes syncable by accident. */
function cfCasPayloadFor(sub){
  if(sub==="core")return payload();
  return (state&&state.training)?state.training:{};}

function cfCasState(sub){
  var t=revTrack(sub);
  return {local:t.local,attempted:t.attempted,success:t.success,
          serverRev:cfCasServerRev(sub),blocked:CF_CAS_BLOCK[sub],
          conflictId:cfCasConflictId(sub)};}

/* A stable per-device diagnostic id. Stored as an opaque random value; the
   server hashes it again before storing, and it never contains health data. */
function cfCasDeviceId(){
  try{
    var k="cf:casdevice",v=localStorage.getItem(k);
    if(!v){v="dev-"+(cfCasRandomIdFallback());localStorage.setItem(k,v);}
    return v;
  }catch(e){return "dev-unknown";}}
function cfCasRandomIdFallback(){
  try{if(typeof crypto!=="undefined"&&crypto.randomUUID)return String(crypto.randomUUID()).replace(/-/g,"");}catch(e){}
  return String(Date.now());}

/* ---- one captured operation --------------------------------------------
   Review C10-P8-01/02/03. Everything a request needs is captured ONCE, before
   any asynchronous work begins, and nothing rereads mutable application state
   afterwards. The previous version canonicalised the payload, hashed it, then
   re-read the payload and the local revision — so an edit landing during the
   hash produced a request whose idempotency key described payload A while its
   body carried payload B, and whose acknowledged revision belonged to neither.

   The payload sent on the wire is parsed back out of the canonical bytes the
   key was derived from, so the two cannot disagree by construction. */
function cfCasCapture(sub){
  var canon=cfCanon(cfCasPayloadFor(sub));
  var frozen=null;
  try{frozen=JSON.parse(canon);}catch(e){frozen=null;}
  return {sub:sub,localRev:revLocal(sub),expectedRev:cfCasServerRev(sub),
          canon:canon,payload:frozen,key:null,token:cfCasRandomIdFallback(),
          /* EXACT session identity (review C10-P9-03). A 16-character suffix
             was a needless weakening: two sessions can share trailing
             characters. The full token is compared IN MEMORY only — the
             operation object is never logged, serialised or persisted. */
          owner:pbUid(),gen:CF_SESSION_GEN,tok:String(pbTok()||""),
          build:APP_BUILD,device:cfCasDeviceId()};}

/* Has the ground moved under this operation? Checked before sending AND before
   applying any response, so a late answer for a signed-out account is inert. */
function cfCasOpDrifted(op){
  return !op||op.owner!==pbUid()||op.gen!==CF_SESSION_GEN||
         op.tok!==String(pbTok()||"");}

function cfCasSend(op,cb){
  var url=pbBase()+"/api/cf/appdata/commit";
  var body={subsystem:op.sub,expectedRev:op.expectedRev,idempotencyKey:op.key,
            payload:op.payload,clientBuild:op.build,deviceId:op.device};
  try{
    fetch(url,{method:"POST",headers:pbHeaders(true),body:JSON.stringify(body)})
      .then(function(r){
        return r.json().then(function(j){cb(r.status,j);},function(){cb(r.status,null);});
      },function(){cb(0,null);});
  }catch(e){cb(0,null);}}

/* ---- scheduling -------------------------------------------------------- */
function cfCasClearTimer(sub){
  if(CF_CAS_TIMER[sub]){clearTimeout(CF_CAS_TIMER[sub]);CF_CAS_TIMER[sub]=null;}}

/* Coalesce: every edit inside the window becomes ONE snapshot. */
function cfCasSchedule(sub,ms){
  if(!syncOn())return;
  cfCasClearTimer(sub);
  CF_CAS_TIMER[sub]=setTimeout(function(){
    CF_CAS_TIMER[sub]=null;cfCasRun(sub);},(ms===undefined)?CF_CAS_DEBOUNCE_MS:ms);}

/* High-intent points sync without waiting for the debounce, and never block. */
function cfCasSyncNow(sub){
  if(sub){cfCasClearTimer(sub);cfCasRun(sub);return;}
  cfCasSyncNow("core");cfCasSyncNow("training");}

/* The subsystem is reserved BEFORE the asynchronous build, not after it, so a
   second trigger during hashing cannot start a second hash or fetch. It records
   that another run is wanted and takes its turn when this one finishes. */
function cfCasSessionNow(){return {owner:pbUid(),gen:CF_SESSION_GEN,tok:String(pbTok()||"")};}
function cfCasSameSession(a,b){
  return !!a&&!!b&&a.owner===b.owner&&a.gen===b.gen&&a.tok===b.tok;}

function cfCasFinishOp(sub){
  CF_CAS_OP[sub]=null;
  var queued=CF_CAS_RERUN[sub];
  CF_CAS_RERUN[sub]=null;                            /* consumed either way */
  if(!queued)return;
  if(!cfCasSameSession(queued,cfCasSessionNow()))return;   /* belonged to another session */
  if(cfCasCanCommit(cfCasState(sub)))cfCasSchedule(sub,0);}

function cfCasRun(sub){
  if(CF_CAS_OP[sub]){CF_CAS_RERUN[sub]=cfCasSessionNow();return;}   /* building OR sending */
  if(!syncOn())return;
  if(!cfCasCanCommit(cfCasState(sub)))return;
  if(cfAccountBlocked&&cfAccountBlocked())return;      /* ownership gates stay preconditions */
  var op=cfCasCapture(sub);
  if(!op.owner||op.payload===null){return;}
  CF_CAS_OP[sub]={phase:"building",op:op};
  cfCasStartOp(sub,op);}

function cfCasStartOp(sub,op){
  cfCasSha256Hex(cfCasIdentity(op.sub,op.expectedRev,op.canon),function(hex){
    if(!cfCasHashValid(hex)){cfCasSetBlock(sub,"invariant",op.token);cfCasFinishOp(sub);return;}
    var key=cfCasKeyFrom(hex);
    if(!key){cfCasSetBlock(sub,"invariant",op.token);cfCasFinishOp(sub);return;}  /* never truncate */
    op.key=key;
    if(cfCasOpDrifted(op)){cfCasFinishOp(sub);return;}   /* cancel without sending */
    cfCasDispatch(sub,op);});}

/* Sending a CAPTURED operation. A retry re-sends this same object, so the
   expected revision, payload bytes and idempotency key are identical (review §7);
   a newer local edit waits its turn behind it rather than silently taking over
   an uncertain request's identity. */
function cfCasDispatch(sub,op){
  if(!CF_CAS_OP[sub])CF_CAS_OP[sub]={phase:"sending",op:op};
  else CF_CAS_OP[sub].phase="sending";
  revAttempt(sub);
  cfCasSend(op,function(status,body){
    if(cfCasOpDrifted(op)){cfCasFinishOp(sub);return;}   /* late, wrong account: inert */
    cfCasHandle(sub,op,status,body||{});});}

/* ---- response disposition ---------------------------------------------- */
function cfCasHandle(sub,op,status,body){
  var d=cfCasDisposition(status,body,sub);

  if(d==="ok"){
    CF_CAS_ATTEMPT[sub]=0;cfCasSetBlock(sub,null,null);CF_CAS_SEQ[sub].retried=false;
    var acked=cfCasAck(revTrack(sub),op.localRev,body.newRev);
    revCommit(sub,op.localRev);                  /* acknowledges ONLY what was sent */
    cfCasSetServerRev(sub,body.newRev);
    cfCasSetBaseline(sub,op.canon);              /* this is now the agreed content */
    cfCasFinishOp(sub);
    try{ if(!CF_CAS_BLOCK.core&&!CF_CAS_BLOCK.training)cfStatusClearSource("cas-network"); }catch(e){}
    if(acked.stillPending){cfCasSchedule(sub,0);return;}  /* an edit landed mid-flight */
    try{cfCasConvergeFrom("commit");}catch(e){}
    return;}

  if(d==="conflict"){cfCasOnConflict(sub,op,body);return;}   /* owns its own finish */

  if(d==="retry"){
    var wait=cfCasRetryDelay(status,CF_CAS_ATTEMPT[sub]);
    CF_CAS_ATTEMPT[sub]=CF_CAS_ATTEMPT[sub]+1;
    if(wait===null){
      cfCasSetBlock(sub,"failed",op.token);
      /* retries exhausted on a 5xx or dead connection: a genuine network
         failure, owned by cas-network and RED — distinct from ordinary pending */
      try{cfStatusSet("cas-network",CF_NETWORK_MSG);}catch(e){}
      cfCasFinishOp(sub);return;}
    /* Re-send the CAPTURED operation: same key, same bytes, same expectedRev. */
    CF_CAS_OP[sub].phase="waiting-retry";
    setTimeout(function(){
      if(cfCasOpDrifted(op)){cfCasFinishOp(sub);return;}
      cfCasDispatch(sub,op);},wait);
    return;}

  /* auth | update | oversize | contract | invariant: no automatic retry. Local
     data stays exactly where it is and stays exportable. */
  cfCasSetBlock(sub,(d==="contract")?"invariant":d,op.token);
  try{ if(d==="auth")cfStatusSet("auth",CF_AUTH_MSG); }catch(e){}
  cfCasFinishOp(sub);}

/* ---- 409 --------------------------------------------------------------- */
function cfCasOnConflict(sub,op,body){
  var serverRev=(body.serverRev===null)?null:body.serverRev;
  if(serverRev!==null)cfCasSetServerRev(sub,serverRev);
  var serverCanon=cfCanon(body.payload===undefined?null:body.payload);
  var verdict=cfCasAutoResolve(serverCanon,op.canon,cfCasBaseline(sub),
                               CF_CAS_SEQ[sub].retried);

  if(verdict==="agree"){
    CF_CAS_ATTEMPT[sub]=0;CF_CAS_SEQ[sub].retried=false;
    revCommit(sub,op.localRev);
    cfCasSetBaseline(sub,serverCanon);
    cfCasFinishOp(sub);
    return;}

  if(verdict==="retry-once"){
    /* The sequence flag lives outside the network-retry counter, which is reset
       on every response — reading that counter meant "already retried" was
       always false and the baseline path could retry after every 409. */
    CF_CAS_SEQ[sub].retried=true;
    cfCasFinishOp(sub);
    cfCasSchedule(sub,0);
    return;}

  /* A genuine conflict. Block the subsystem IMMEDIATELY — before the async
     recovery write — so an edit arriving during preservation cannot schedule
     another commit into a conflict that is still being made actionable. */
  cfCasSetBlock(sub,"preserving",op.token);cfCasPreserveBegin(sub);
  cfCasFinishOp(sub);
  var id=cfCasRecNewId(sub);
  if(!id){cfCasSetBlock(sub,"recovery",op.token);return;}
  cfCasRecWrite(id,sub,serverRev===null?0:serverRev,
    JSON.stringify(body.payload===undefined?null:body.payload),function(ok,manOrReason,cap){
      if(cfCasOpDrifted(op)){
        /* The session changed while the recovery artifact was being written.
           Publishing nothing is necessary but not sufficient: a VERIFIED
           artifact may already exist, and returning here would orphan it. It is
           purged through the locked API using the capability captured for that
           write — never through the public purge, which addresses whichever
           account is live now (review C10-P9-02). */
        if(ok&&cap&&cap.purge)cap.purge(function(){});
        /* Clear the transient state THIS operation set, and only that. A late
           callback must not unpause a NEWER conflict — ownership is proved by
           the operation token, not by the block happening to read
           "preserving". */
        if(cfCasOwnsBlock(sub,op.token)){
          cfCasSetBlock(sub,null,null);
          CF_CAS_SEQ[sub].retried=false;}
        return;}
      if(!ok){cfCasSetBlock(sub,"recovery",op.token);return;}
      cfCasSetConflictId(sub,id);                /* only now is it actionable */
      if(cfCasOwnsBlock(sub,op.token))cfCasSetBlock(sub,null,null);  /* conflictId is the block now */
    });}

/* ---- re-point the frozen entry points ---------------------------------- */
/* The revision bump is UNCONDITIONAL. Commit 1c fixed exactly this: an edit
   made while signed out must still advance the local revision, or a later
   session sees a device that looks clean and adopts stale server data over
   newer local work. My first version of this override reinstated the
   `if(!syncOn())return` guard and silently undid that fix — caught by the
   existing c1c suite, which is the argument for never deleting an old test
   just because a new commit owns the code path. Only the pending marker and
   the network schedule are gated on being signed in. */
scheduleCloudPush=function(){
  revBump("core");
  if(syncOn()){cfSetPending("push");cfCasSchedule("core");}};
scheduleTrainingPush=function(){
  revBump("training");
  if(syncOn()){cfSetPending("push");cfCasSchedule("training");}};

/* ---- conflict workflow and status model ---------------------------------
   Architect specification §1 and §3. The athlete never sees "core",
   "training", "revision", "CAS" or a record id — they see which part of their
   data is affected and what will happen to it.

   Every destructive choice is recovery-first and context-checked: the copy that
   is about to be replaced is stored and VERIFIED before anything is replaced,
   and the operation aborts if the account, session, subsystem revision,
   conflict or recovery artifact moved while that was happening. */
var CF_CAS_LABEL={core:"Health & progress",training:"Training & workouts"};

function cfCasConflictSubs(){
  var out=[];
  if(cfCasConflictId("core"))out.push("core");
  if(cfCasConflictId("training"))out.push("training");
  return out;}

/* ---- status (spec §3.1) ------------------------------------------------
   Priority order lives in cfCasStatus; this maps a subsystem's runtime state
   onto one of the seven names. Revisions never reach the athlete UI. */
function cfCasStatusFor(sub){
  if(CF_CAS_BLOCK[sub]==="update")return "update";
  /* A recovery-blocked subsystem may still hold a conflict id, but its stored
     copy could not be verified — so neither destructive choice may be offered.
     Reporting "Sync needs your choice" would invite the athlete into a screen
     whose options are all unavailable, and would imply the online copy is
     safely preserved when that is exactly what failed (spec C5). */
  if(CF_CAS_BLOCK[sub]==="recovery")return "failed";
  if(cfCasConflictId(sub))return "conflict";
  if(CF_CAS_BLOCK[sub]==="auth")return "auth";
  if(CF_CAS_BLOCK[sub]==="failed"||CF_CAS_BLOCK[sub]==="oversize"||
     CF_CAS_BLOCK[sub]==="invariant"||CF_CAS_BLOCK[sub]==="recovery")return "failed";
  if(CF_CAS_OP[sub])return "syncing";
  if(revIsDirty(sub))return "pending";
  return "synced";}
function cfCasCompactStatus(){return cfCasStatus(cfCasStatusFor("core"),cfCasStatusFor("training"));}

/* ---- FIX-004: a successful upload must CLEAR the "not uploaded yet" state ---
   scheduleCloudPush does two things on every edit: cfSetPending("push"), which
   sets the LEGACY sync state to error with "changes on this device aren't
   uploaded yet — tap to upload", and cfCasSchedule(), which does the real work.
   The CAS success path acked revisions and set the baseline but never touched
   the legacy marker — and syncDotClass() falls through to the legacy state
   whenever the conflict centre has nothing to show. So after a completely
   successful commit the athlete saw a RED dot claiming their data was not
   uploaded. Found on the Product Owner's iPhone during the canary day-one
   restart, 2026-07-30, and reproduced: commit 200 / newRev 1 / CAS "synced" /
   dirty false, dot still "bad".

   No data was ever at risk — the data was uploaded — but a status that cries
   wolf in the alarming direction is worse than useless in a health app: it
   teaches the athlete to ignore the one indicator that must be believed when a
   real pending state appears.

   Only clears when the WHOLE CAS surface is settled, so a still-pending or
   blocked sibling subsystem keeps the honest warning. */
function cfCasSyncLegacyStatus(){
  try{
    if(cfCasCompactStatus()!=="synced")return;   /* something really is outstanding */
    if(revIsDirty("core")||revIsDirty("training"))return;
    cfClearPending();
    setLastSync();
    setSync("ok");
    try{render();}catch(e){}
  }catch(e){/* status is cosmetic; never break a completed commit over it */}}
var CF_CAS_STATUS_TEXT={
  update:"Update required — reload the app",
  conflict:"Sync needs your choice",
  auth:"Sign in to sync",
  failed:"Couldn’t sync — changes are safe here",
  pending:"Saved on this device",
  syncing:"Syncing…",
  synced:"Synced"};
function cfCasStatusText(state){return CF_CAS_STATUS_TEXT[state]||CF_CAS_STATUS_TEXT.synced;}

/* ---- resolution operations (review C10-P12-01..05) ----------------------
   The scheduler already treats a request as one owned, drift-checked operation.
   The manual choices did not, and every gap the review found follows from that:
   a double tap could start two overwrites, a late response could apply to
   whichever account was signed in when it landed, and an artifact created by an
   aborted choice was left behind.

   So a resolution is now an operation too — one per subsystem, owning its
   action, session, revisions, conflict, token and every artifact it creates. */
var CF_CAS_RES={core:null,training:null};

function cfCasResolveCtx(sub){
  return cfCasCtx(sub,pbUid(),CF_SESSION_GEN,revLocal(sub),
                  cfCasConflictId(sub),cfCasServerRev(sub),cfCasConflictId(sub));}

/* Only the operation that owns the subsystem may act on it. A repeat activation
   is ignored rather than queued: the athlete pressing twice means one decision,
   not two. */
function cfCasResBegin(sub,action){
  if(CF_CAS_RES[sub])return null;                       /* already resolving */
  var op={action:action,sub:sub,token:cfCasRandomIdFallback(),
          ctx:cfCasResolveCtx(sub),tok:String(pbTok()||""),
          artifacts:[]};                                /* capabilities to clean up */
  CF_CAS_RES[sub]=op;
  return op;}
function cfCasResOwns(sub,op){return !!op&&CF_CAS_RES[sub]===op;}
function cfCasResEnd(sub,op){if(CF_CAS_RES[sub]===op)CF_CAS_RES[sub]=null;}

/* Has anything this decision depends on moved? Owner, session token, subsystem
   revision, conflict identity, server revision — plus the operation still being
   the one that owns the subsystem. */
function cfCasResDrifted(sub,op){
  if(!cfCasResOwns(sub,op))return true;
  if(op.tok!==String(pbTok()||""))return true;
  return cfCasCtxDrifted(op.ctx,cfCasResolveCtx(sub));}

/* Everything a resolution creates is purged through the capability captured
   when it was written — never through the public purge, which addresses
   whichever account is live now. */
function cfCasResCleanup(op){
  if(!op)return;
  for(var i=0;i<op.artifacts.length;i++){
    var cap=op.artifacts[i];
    if(cap&&cap.purge){try{cap.purge(function(){});}catch(e){}}}
  op.artifacts=[];}

function cfCasResFail(sub,op,why,cb){
  cfCasResCleanup(op);
  cfCasResEnd(sub,op);
  cb(false,why);}

/* Read the referenced recovery artifact and prove it before offering or acting
   on any choice. A conflict whose artifact does not verify is not actionable —
   the subsystem falls back to the recovery-blocked state (spec C5). */
function cfCasConflictArtifact(sub,cb){
  var id=cfCasConflictId(sub);
  if(!id){cb(null,"no-conflict");return;}
  cfCasRecRead(id,{account:pbUid(),sub:sub,serverRev:cfCasServerRev(sub),rec:id},function(payload,why){
    if(payload===null){cb(null,why||"unverified");return;}
    cb(payload,null);});}

/* ---- choice 1: Keep this device's changes (default) --------------------
   Nothing is sent, nothing is replaced, the conflict stays unresolved and the
   subsystem stays pending. The online copy is already stored and verified — it
   was written before the card existed — so this choice has nothing to preserve
   and nothing to destroy. */
function cfCasKeepLocal(sub,cb){
  var op=cfCasResBegin(sub,"keep");
  if(!op){cb(false,"busy");return;}
  cfCasConflictArtifact(sub,function(payload,why){
    if(payload===null){cfCasSetBlock(sub,"recovery",null);cfCasResFail(sub,op,why,cb);return;}
    cfCasResEnd(sub,op);
    cb(true,null);});}                          /* stays pending, stays conflicted */

/* ---- choice 2: Use this device everywhere -----------------------------
   Submit the LATEST local payload against the captured server revision. A
   second 409 does not loop and does not silently win: the newer online copy is
   preserved and VERIFIED before the old reference is replaced, and the athlete
   is told the online copy changed again. */
var CF_CAS_RECHOOSE={core:false,training:false};
function cfCasUseThisDevice(sub,cb){
  var op=cfCasResBegin(sub,"use-device");
  if(!op){cb(false,"busy");return;}
  cfCasConflictArtifact(sub,function(payload,why){
    if(payload===null){cfCasSetBlock(sub,"recovery",null);cfCasResFail(sub,op,why,cb);return;}
    if(cfCasResDrifted(sub,op)){cfCasResFail(sub,op,"drift",cb);return;}
    var canon=cfCanon(cfCasPayloadFor(sub));
    var frozen=null;try{frozen=JSON.parse(canon);}catch(e){frozen=null;}
    if(frozen===null){cfCasResFail(sub,op,"invalid",cb);return;}
    var localRev=revLocal(sub);
    cfCasSha256Hex(cfCasIdentity(sub,cfCasServerRev(sub),canon),function(hex){
      var key=cfCasHashValid(hex)?cfCasKeyFrom(hex):null;   /* new key: expectedRev moved */
      if(!key){cfCasResFail(sub,op,"invariant",cb);return;}
      if(cfCasResDrifted(sub,op)){cfCasResFail(sub,op,"drift",cb);return;}
      var req={sub:sub,expectedRev:cfCasServerRev(sub),key:key,canon:canon,payload:frozen,
               localRev:localRev,build:APP_BUILD,device:cfCasDeviceId()};
      cfCasSend(req,function(status,body){
        body=body||{};
        /* The response may be late. Applying it to whoever is signed in now
           would transfer one account's acknowledgement to another. */
        if(cfCasResDrifted(sub,op)){cfCasResFail(sub,op,"drift",cb);return;}
        var d=cfCasDisposition(status,body,sub);
        if(d==="ok"){
          revCommit(sub,req.localRev);
          cfCasSetServerRev(sub,body.newRev);
          cfCasSetBaseline(sub,canon);
          cfCasResolved(sub,op);
          cfCasResEnd(sub,op);
          cb(true,null);return;}
        if(d==="conflict"){
          cfCasReplaceConflict(sub,op,body,function(ok2){
            if(ok2)CF_CAS_RECHOOSE[sub]=true;
            cfCasResEnd(sub,op);
            cb(false,ok2?"changed-again":"recovery");});
          return;}
        cfCasSetBlock(sub,(d==="contract")?"invariant":d,null);
        cfCasResFail(sub,op,d,cb);});});});}

/* ---- choice 3: Use the online copy here --------------------------------
   The device's CURRENT version is stored and verified first, then the server is
   re-read: a captured payload is never adopted merely because it was valid once.
   Refresh and adoption belong to the same owned operation, so a late refresh
   cannot adopt into a session or a conflict that has moved on. */
function cfCasUseOnlineCopy(sub,cb){
  var op=cfCasResBegin(sub,"use-online");
  if(!op){cb(false,"busy");return;}
  cfCasConflictArtifact(sub,function(serverPayload,why){
    if(serverPayload===null){cfCasSetBlock(sub,"recovery",null);cfCasResFail(sub,op,why,cb);return;}
    if(cfCasResDrifted(sub,op)){cfCasResFail(sub,op,"drift",cb);return;}
    var localId=cfCasRecNewId(sub);
    if(!localId){cfCasSetBlock(sub,"recovery",null);cfCasResFail(sub,op,"entropy",cb);return;}
    /* 1. preserve THIS DEVICE's version before replacing it */
    cfCasRecWrite(localId,sub,cfCasServerRev(sub),cfCanon(cfCasPayloadFor(sub)),function(ok,man,cap){
      if(!ok){cfCasSetBlock(sub,"recovery",null);cfCasResFail(sub,op,"recovery",cb);return;}
      if(cap)op.artifacts.push(cap);            /* cleaned up if we abort below */
      if(cfCasResDrifted(sub,op)){cfCasResFail(sub,op,"drift",cb);return;}
      /* 2. is the online copy still what the athlete is choosing against? */
      cfCasRefreshServerRev(sub,function(rev,err){
        if(err){cfCasResFail(sub,op,err,cb);return;}
        if(cfCasResDrifted(sub,op)){cfCasResFail(sub,op,"drift",cb);return;}
        if(rev!==cfCasServerRev(sub)){
          CF_CAS_RECHOOSE[sub]=true;
          cfCasResFail(sub,op,"changed-again",cb);return;}
        /* 3. adopt — one guarded destructive transition */
        var parsed=null;try{parsed=JSON.parse(serverPayload);}catch(e){parsed=null;}
        if(parsed===null){cfCasResFail(sub,op,"unverified",cb);return;}
        if(cfCasResDrifted(sub,op)){cfCasResFail(sub,op,"drift",cb);return;}
        cfCasAdopt(sub,parsed);
        revClean(sub);
        cfCasSetBaseline(sub,cfCanon(parsed));
        op.artifacts=[];                        /* the safety copy is kept, deliberately */
        cfCasResolved(sub,op);
        cfCasResEnd(sub,op);
        cb(true,null);});});});}

/* Read-only: the current server revision for this subsystem. */
function cfCasRefreshServerRev(sub,cb){
  try{
    pbGetRecord(function(rec,err){
      if(err){cb(null,"offline");return;}
      if(!rec){cb(0,null);return;}
      var f=(sub==="core")?"coreRev":"trainingRev";
      cb(typeof rec[f]==="number"?rec[f]:0,null);});
  }catch(e){cb(null,"offline");}}

function cfCasAdopt(sub,parsed){
  if(sub==="training"){state.training=parsed;saveTrainingLocal();return;}
  applyCloudRaw(parsed);saveLocal();}

/* A resolved conflict releases the subsystem. Only the operation that owns the
   subsystem may resolve it, so a late callback cannot clear a newer conflict. */
function cfCasResolved(sub,op){
  if(op&&!cfCasResOwns(sub,op))return;
  var id=cfCasConflictId(sub);
  cfCasSetConflictId(sub,null);
  CF_CAS_RECHOOSE[sub]=false;
  CF_CAS_SEQ[sub].retried=false;
  cfCasSetBlock(sub,null,null);
  if(id)cfCasRecPurge(id,function(){});          /* the copy has served its purpose */
  cfCasSchedule(sub,0);}

/* Replace a conflict with a newer one. The ORIGINAL stays actionable until the
   newer artifact is written AND verified; only then is the reference swapped
   and the old copy purged. A failure or a drift leaves the original intact and
   removes the candidate, rather than leaving a misleading half-state. */
function cfCasReplaceConflict(sub,op,body,cb){
  if(!cfCasConflictBody(body,sub)){cfCasSetBlock(sub,"invariant",null);cb(false);return;}
  var serverRev=(body.serverRev===null)?0:body.serverRev;
  var old=cfCasConflictId(sub);
  var id=cfCasRecNewId(sub);
  if(!id){cfCasSetBlock(sub,"recovery",null);cb(false);return;}
  cfCasRecWrite(id,sub,serverRev,JSON.stringify(body.payload===undefined?null:body.payload),
    function(ok,man,cap){
      if(!ok){cfCasSetBlock(sub,"recovery",null);cb(false);return;}   /* original intact */
      if(op&&cfCasResDrifted(sub,op)){
        if(cap&&cap.purge)cap.purge(function(){});                    /* candidate removed */
        cb(false);return;}                                            /* original intact */
      cfCasSetServerRev(sub,serverRev);
      cfCasSetConflictId(sub,id);                                     /* swap AFTER verify */
      if(!old||old===id){cb(true);return;}
      /* The new reference is committed and stays committed. Deleting the old
         copy is a separate obligation whose OUTCOME is observed: a failure is
         recorded for retry rather than reported as done, so repeated
         replacements cannot quietly accumulate verified copies of the
         athlete's data (review C10-P13-01). Never roll the swap back for it. */
      var scope=cfCasRecScope();
      cfCasRecPurgeTracked(scope,old,function(){cb(true);});});}

/* ---- the conflict centre (rendered) -------------------------------------
   Architect specification §1.1–1.3 and §1.6. The athlete is told what happened
   to their data and what each choice will do to it, in those words. Nothing
   here exposes a revision, a subsystem code, CAS, a payload or a record id.

   One surface, one card per affected section, resolved independently. There is
   deliberately no "resolve all": a single tap that overwrites both halves of
   someone's history is not a convenience. */
var CF_CAS_COPY={
  heading:"Changes were made on another device",
  body:function(label){
    return "Your changes are safe on this device. Choose what should happen to "+label+".";},
  keep:{label:"Keep this device’s changes",
        help:"Keep working here. Sync for this section stays paused until you choose whether to update the online copy."},
  device:{label:"Use this device’s copy online",
          help:"Replace the online copy with this device’s version. The current online copy will be saved first.",
          confirm:"Replace the online copy with this device’s version?"},
  online:{label:"Use the online copy on this device",
          help:"Replace this device’s version. This device’s current version will be saved first.",
          confirm:"Replace this device’s version with the online copy?"},
  changedAgain:"The online copy changed again. Review your choice.",
  preserving:"Saving a copy of the online version…",
  blocked:"We couldn’t save a copy of the online version, so these options aren’t available yet.",
  blockedActions:"Your data is safe on this device. You can export it or try again.",
  working:"Working on it…",
  close:"Close",
  none:"Nothing needs your attention right now."};

function cfCasEsc(t){
  return String(t===undefined||t===null?"":t)
    .replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")
    .replace(/"/g,"&quot;").replace(/'/g,"&#39;");}

/* One card. `state` is "choose" | "preserving" | "blocked" | "changed-again". */
function cfCasCardHTML(sub,state,isFirst){
  var label=CF_CAS_LABEL[sub],id="cfcard-"+sub;
  /* A resolution already owns this subsystem. cfCasResBegin refuses the second
     one, but refusing it silently is not enough in a browser: a real athlete
     taps twice, and the second tap must be impossible rather than ignored.
     `disabled` makes it unclickable AND unfocusable; the state is also named,
     because a control that stops responding without explanation reads as a bug
     to the person using it. */
  var busy=!!CF_CAS_RES[sub],dis=busy?' disabled':'';
  var h='<section class="wl-card cf-conflict-card" role="group" aria-labelledby="'+id+'-title"'+
        (busy?' aria-busy="true"':'')+'>';
  /* Focusable so that focus has somewhere sensible to land inside the card
     when the control that had it disappears (resolved, or gone busy). */
  h+='<h3 id="'+id+'-title" class="cf-conflict-title" tabindex="-1">'+cfCasEsc(label)+'</h3>';

  /* NO role="status" / aria-live anywhere in this markup. These strings are
     produced by a function that is re-run and re-mounted whenever anything
     changes; a live region inside replaced markup is destroyed and recreated,
     and assistive tech announces the whole thing again every time. The result
     is "Saving a copy of the online version…" repeated on every repaint.
     Announcement is therefore the job of ONE stable region outside this markup,
     written only when the message actually changes — see cfCasAnnouncement()
     and cfCasAnnounce() in the browser-wiring block. */
  if(state==="blocked"){
    h+='<p class="cf-conflict-body">'+cfCasEsc(CF_CAS_COPY.blocked)+'</p>';
    h+='<p class="cf-conflict-help">'+cfCasEsc(CF_CAS_COPY.blockedActions)+'</p>';
    /* Retry is the action that restores the intended workflow, so it leads.
       Export is the fallback and must not compete with it (C10-UX ruling 5). */
    h+='<button class="wl-btn wl-btn-primary wl-full cf-action" data-act="cf:retry-recovery" data-sub="'+sub+'"'+dis+'>Try again</button>';
    h+='<button class="wl-btn wl-btn-ghost wl-full cf-action cf-action-secondary" data-act="cf:export">Export a copy</button>';
    if(busy)h+='<p class="cf-conflict-busy">'+cfCasEsc(CF_CAS_COPY.working)+'</p>';
    return h+'</section>';}

  if(state==="preserving"){
    h+='<p class="cf-conflict-body">'+cfCasEsc(CF_CAS_COPY.preserving)+'</p>';
    return h+'</section>';}

  /* Focusable (tabindex=-1) but not a live region: when the online copy changes
     again the athlete is sent HERE — to the explanation — not to a destructive
     button they were already reaching for (C10-UX-16). */
  if(state==="changed-again")
    h+='<p id="'+id+'-note" class="cf-conflict-note" tabindex="-1">'+cfCasEsc(CF_CAS_COPY.changedAgain)+'</p>';

  h+='<p class="cf-conflict-body">'+cfCasEsc(CF_CAS_COPY.body(label))+'</p>';
  /* Focus order is the safety order: the non-destructive default first. */
  /* NO autofocus. Focusing an action puts the athlete on a choice before they
     have heard what happened, and an immediate Enter would confirm it. The
     centre focuses its HEADING instead when the athlete opens it explicitly,
     and background discovery never moves focus at all (C10-UX-11..14). */
  h+='<button class="wl-btn wl-btn-primary wl-full cf-action" data-act="cf:keep" data-sub="'+sub+'"'+
     ' aria-describedby="'+id+'-keep-help"'+dis+'>'+cfCasEsc(CF_CAS_COPY.keep.label)+'</button>';
  h+='<p id="'+id+'-keep-help" class="cf-conflict-help">'+cfCasEsc(CF_CAS_COPY.keep.help)+'</p>';
  h+='<button class="wl-btn wl-btn-ghost wl-full cf-action" data-act="cf:use-device" data-sub="'+sub+'"'+
     ' aria-describedby="'+id+'-device-help"'+dis+'>'+cfCasEsc(CF_CAS_COPY.device.label)+'</button>';
  h+='<p id="'+id+'-device-help" class="cf-conflict-help">'+cfCasEsc(CF_CAS_COPY.device.help)+'</p>';
  h+='<button class="wl-btn wl-btn-ghost wl-full cf-action" data-act="cf:use-online" data-sub="'+sub+'"'+
     ' aria-describedby="'+id+'-online-help"'+dis+'>'+cfCasEsc(CF_CAS_COPY.online.label)+'</button>';
  h+='<p id="'+id+'-online-help" class="cf-conflict-help">'+cfCasEsc(CF_CAS_COPY.online.help)+'</p>';
  if(busy)h+='<p class="cf-conflict-busy">'+cfCasEsc(CF_CAS_COPY.working)+'</p>';
  return h+'</section>';}

/* Preservation usually finishes in a few milliseconds. Showing a card for one
   frame is visual noise, so the state is truthful but DELAYED: nothing is shown
   for the first 400 ms, and if it is still running after that the athlete is
   told what is happening (C10-UX-17/18). */
var CF_CAS_PRESERVE_MS=400;
var CF_CAS_PRESERVE_AT={core:0,training:0};
function cfCasPreserveBegin(sub){CF_CAS_PRESERVE_AT[sub]=Date.now();}
function cfCasPreserveVisible(sub,now){
  if(CF_CAS_BLOCK[sub]!=="preserving")return false;
  var at=CF_CAS_PRESERVE_AT[sub]||0;
  return ((now===undefined?Date.now():now)-at)>=CF_CAS_PRESERVE_MS;}

function cfCasCardState(sub,now){
  if(CF_CAS_BLOCK[sub]==="recovery")return "blocked";
  if(CF_CAS_BLOCK[sub]==="preserving")
    return cfCasPreserveVisible(sub,now)?"preserving":"hidden";
  if(CF_CAS_RECHOOSE[sub])return "changed-again";
  return "choose";}

/* ---- the ONE predicate for "the centre has something to show" -----------
   The view used to work this out inline while the entry point used a separate
   status check, and the two disagreed: a recovery-blocked subsystem maps to the
   safe failure state rather than to "conflict", so the header opened the centre
   for an unresolved conflict but NOT for a blocked one — a correctly rendered
   card with no way in, which is the exact defect browser testing had just
   found. Both now read the same function, so they cannot drift apart again.

   Returns the subsystems worth showing, plus whether something is happening
   that is deliberately not shown yet (a sub-400ms preservation). */
function cfCasCentreSubs(now){
  var subs=[],hidden=false;
  now=(now===undefined)?Date.now():now;
  ["core","training"].forEach(function(sub){
    var active=cfCasConflictId(sub)||CF_CAS_BLOCK[sub]==="recovery"||CF_CAS_BLOCK[sub]==="preserving";
    if(!active)return;
    if(CF_CAS_BLOCK[sub]==="preserving"&&!cfCasPreserveVisible(sub,now)){hidden=true;return;}
    subs.push(sub);});
  return {subs:subs,hidden:hidden};}

/* True when the centre holds actionable or explanatory state: an unresolved
   verified conflict, a recovery block, a changed-again, or a preservation that
   has become visible. A sole hidden preservation is deliberately false — it
   must neither open the centre nor render one. */
function cfCasCentreHasWorkflow(){return cfCasCentreSubs().subs.length>0;}

/* Severity for the header control. Recovery-blocked is a FAILED preservation —
   the online copy could not be saved and the destructive choices are withdrawn
   — so it takes the app's error severity. An unresolved conflict is not a
   failure: both versions are safe and the athlete simply has to choose. The
   higher severity wins when both exist. */
function cfCasCentreSeverity(){
  var subs=cfCasCentreSubs().subs,sev=null;
  for(var i=0;i<subs.length;i++){
    if(CF_CAS_BLOCK[subs[i]]==="recovery")return "bad";
    sev="warn";}
  return sev;}

function cfCasConflictCenterHTML(){
  var now=Date.now(),found=cfCasCentreSubs(now);
  var subs=found.subs,hidden=found.hidden;

  /* If the ONLY thing happening is a preservation too brief to show, render
     NOTHING — not the empty state. Saying "Nothing needs your attention right
     now" while a conflict is actively being preserved is false, and it is the
     kind of false that matters: it tells the athlete their data is settled at
     the exact moment it is not. My previous caption claimed this state rendered
     nothing; the code rendered the heading and that sentence. The Architect
     read the code rather than the caption. */
  if(!subs.length&&hidden)return "";

  var h='<div class="cf-conflict-center" role="region" aria-labelledby="cf-conflict-heading">';
  h+='<h2 id="cf-conflict-heading" tabindex="-1">'+cfCasEsc(CF_CAS_COPY.heading)+'</h2>';
  /* The empty state is only true when no conflict, no recovery block and no
     preservation exists at all. */
  if(!subs.length)
    return h+'<p class="cf-conflict-body">'+cfCasEsc(CF_CAS_COPY.none)+'</p>'+cfCasCloseHTML()+'</div>';
  subs.forEach(function(sub,i){h+=cfCasCardHTML(sub,cfCasCardState(sub,now),i===0);});
  /* Close comes LAST, in the DOM and on the screen. It was briefly in the
     header next to the heading, which reads well but put a control between the
     explanation and the first choice: the athlete's first Tab landed on Close
     rather than on "Keep this device's changes". Chromium's own tab order is
     what caught it. Keeping DOM order equal to visual order means the tab order
     is heading → safe default → the rest → close, with no tabindex tricks and
     nothing for a screen reader to read out of sequence. */
  return h+cfCasCloseHTML()+'</div>';}

function cfCasCloseHTML(){
  return '<button class="wl-btn wl-btn-ghost wl-full cf-conflict-close" '+
         'data-act="cf:close-conflicts">'+cfCasEsc(CF_CAS_COPY.close)+'</button>';}

/* The compact indicator. Tapping it opens the centre; it is never a modal, so a
   background discovery cannot interrupt an active workout (spec §1.6). */
function cfCasStatusHTML(){
  var st=cfCasCompactStatus();
  var needs=(st==="conflict");
  /* No aria-live here either. This button is re-mounted by the app's own render
     — 298 call sites — so a live region on it would re-announce the sync state
     on every unrelated repaint. cfCasAnnounce() owns announcement. */
  return '<button class="wl-sdot cf-status cf-status-'+st+'" data-act="cf:open-conflicts"'+
         ' aria-label="'+cfCasEsc(cfCasStatusText(st))+'">'+
         cfCasEsc(cfCasStatusText(st))+(needs?' <span aria-hidden="true">›</span>':'')+'</button>';}

/* Per-subsystem detail, shown when the athlete opens the indicator. */
function cfCasStatusDetailHTML(){
  var h='<ul class="cf-status-detail" role="list">';
  ["core","training"].forEach(function(sub){
    h+='<li><span class="cf-status-name">'+cfCasEsc(CF_CAS_LABEL[sub])+'</span> '+
       '<span class="cf-status-state">'+cfCasEsc(cfCasStatusText(cfCasStatusFor(sub)))+'</span></li>';});
  return h+'</ul>';}

/* Interruption policy: a conflict found in the background never takes over the
   screen. During an active workout it is a quiet status change plus one
   notification, and the centre opens only when the athlete asks for it. */
/* Explicit opening moves focus to the heading — the explanation — not to an
   action. Closing returns focus to whatever opened the centre (C10-UX-12/15). */
var CF_CAS_OPENER=null;
function cfCasOpenConflictCenter(openerEl){
  CF_CAS_OPENER=openerEl||null;
  try{
    var h=document.getElementById("cf-conflict-heading");
    if(h&&h.focus)h.focus();
  }catch(e){}
  return true;}
function cfCasCloseConflictCenter(){
  try{if(CF_CAS_OPENER&&CF_CAS_OPENER.focus)CF_CAS_OPENER.focus();}catch(e){}
  CF_CAS_OPENER=null;
  return true;}

function cfCasMayInterrupt(){
  try{return !(state&&state.workout);}catch(e){return true;}}


/* ============================================================
   HARDENING — COMMIT 10b: BROWSER WIRING
   The conflict centre existed as functions returning strings. This block
   connects those strings to a real browser: a stable host, a repaint that
   does not destroy focus, one live region that announces a change once
   rather than on every repaint, delegated activation with confirmations,
   and the interruption policy.

   Three things only become visible once the view is in a document, and all
   three are corrected here rather than papered over:

   (1) Live regions cannot live inside repainted markup. `role="status"` on a
       paragraph that is re-mounted whenever anything changes re-announces
       itself every time. Announcement now belongs to ONE stable node.
   (2) A repaint that replaces innerHTML unconditionally destroys the element
       the athlete is currently on. The centre therefore repaints only when
       its own state actually changes, and restores focus deliberately.
   (3) The app's render() rebuilds #app in 298 places. Anything mounted
       inside it would be torn down constantly, so the centre is a sibling
       of #app with its own lifecycle.
   ============================================================ */

/* @testable-start C10B */

/* ---- what should be announced ------------------------------------------
   Pure: the announcement for the CURRENT state. Announcing is a separate,
   change-guarded step, so this can be called as often as we like. */
function cfCasAnnouncement(){
  var out=[],now=Date.now();
  ["core","training"].forEach(function(sub){
    var busy=cfCasConflictId(sub)||CF_CAS_BLOCK[sub]==="recovery"||CF_CAS_BLOCK[sub]==="preserving";
    if(!busy)return;
    var st=cfCasCardState(sub,now);
    if(st==="hidden")return;                 /* a brief preservation is silent */
    var label=CF_CAS_LABEL[sub];
    if(st==="blocked")out.push(label+": "+CF_CAS_COPY.blocked);
    else if(st==="preserving")out.push(label+": "+CF_CAS_COPY.preserving);
    else if(st==="changed-again")out.push(label+": "+CF_CAS_COPY.changedAgain);
    else out.push(label+": "+CF_CAS_COPY.heading);});
  return out.join(" ");}

/* Everything the rendered markup depends on. Equal signature → identical
   markup → no DOM write, no lost focus, no repeated announcement. Card state
   is included rather than derived, so the 400 ms preservation threshold
   crossing counts as a change. */
function cfCasViewSig(){
  var now=Date.now();
  return ["core","training"].map(function(sub){
    return [sub,cfCasConflictId(sub)||"",CF_CAS_BLOCK[sub]||"",
            CF_CAS_RECHOOSE[sub]?1:0,cfCasCardState(sub,now),
            CF_CAS_RES[sub]?1:0].join("|");}).join("//")+
         "//open="+(CF_CAS_OPEN?1:0);}
/* @testable-end C10B */

var CF_CAS_OPEN=false;
var CF_CAS_SIG=null;
var CF_CAS_SAID=null;
var CF_CAS_PREV={core:null,training:null};
var CF_CAS_PRESERVE_T=null;

function cfCasHostEl(){
  try{
    var el=document.getElementById("cf-conflict-host");
    if(el)return el;
    el=document.createElement("div");
    el.id="cf-conflict-host";
    el.className="cf-conflict-host";
    document.body.appendChild(el);
    return el;
  }catch(e){return null;}}

/* The single stable live region. Created once, never replaced, written only
   when the message changes — that is the whole point of it. */
function cfCasLiveEl(){
  try{
    var el=document.getElementById("cf-cas-live");
    if(el)return el;
    el=document.createElement("div");
    el.id="cf-cas-live";
    el.className="cf-sr";
    el.setAttribute("role","status");
    el.setAttribute("aria-live","polite");
    document.body.appendChild(el);
    return el;
  }catch(e){return null;}}

function cfCasAnnounce(){
  var say=cfCasAnnouncement();
  if(say===CF_CAS_SAID)return false;        /* unchanged: stay silent */
  CF_CAS_SAID=say;
  try{var el=cfCasLiveEl();if(el)el.textContent=say;}catch(e){}
  return true;}

/* ---- focus across a repaint --------------------------------------------
   A control is identified by what it DOES, not by object identity, because
   the element itself is replaced. */
function cfCasFocusKey(el){
  if(!el||!el.getAttribute)return null;
  var a=el.getAttribute("data-act");
  if(a)return "act:"+a+"|"+(el.getAttribute("data-sub")||"");
  if(el.id)return "id:"+el.id;
  return null;}

function cfCasFindByKey(host,key){
  if(!host||!key||!host.querySelector)return null;
  try{
    if(key.indexOf("id:")===0)return document.getElementById(key.slice(3));
    var rest=key.slice(4),bar=rest.lastIndexOf("|");
    var act=rest.slice(0,bar),sub=rest.slice(bar+1);
    var sel='[data-act="'+act+'"]'+(sub?'[data-sub="'+sub+'"]':"");
    return host.querySelector(sel);
  }catch(e){return null;}}

/* Focus, and PROVE it moved. Calling .focus() on an element that cannot take
   focus — a plain heading, a disabled control, a display:none node — is silent:
   nothing throws, focus stays where it was or falls to <body>, and a function
   that returns true here reports a restoration that did not happen. Every
   restoration path below is only as honest as this predicate. */
function cfCasFocus(el){
  try{
    if(!el||!el.focus)return false;
    el.focus();
    return document.activeElement===el;
  }catch(e){return false;}}

/* Visible and enabled, as the browser sees it — not as the markup claims. */
function cfCasFocusable(el){
  try{
    if(!el||el.disabled)return false;
    if(el.getAttribute&&el.getAttribute("aria-disabled")==="true")return false;
    if(!cfCasConnected(el))return false;
    var r=el.getBoundingClientRect();
    if(!(r.width>0&&r.height>0))return false;
    var s=(window.getComputedStyle?getComputedStyle(el):null);
    if(s&&(s.visibility==="hidden"||s.display==="none"))return false;
    return true;
  }catch(e){return false;}}

/* A heading is the safest contextual landing place when the opener is gone, but
   it is not focusable on its own. Give it the same tabindex="-1" the centre's
   own heading carries — programmatically focusable, never in the tab order —
   and leave it there: removing it immediately would invalidate the focus we
   just placed, and a permanent -1 changes nothing for anyone tabbing through. */
function cfCasFocusHeading(el){
  try{
    if(!el||!cfCasFocusable(el))return false;
    if(!el.hasAttribute("tabindex"))el.setAttribute("tabindex","-1");
    return cfCasFocus(el);
  }catch(e){return false;}}

function cfCasInHost(host,el){
  try{return !!(host&&el&&host.contains&&host.contains(el));}catch(e){return false;}}

/* ---- the repaint --------------------------------------------------------
   Called from anywhere; cheap and idempotent when nothing has changed. */
function cfCasPaint(){
  var host=cfCasHostEl();
  cfCasAnnounce();
  cfCasPreserveArm();
  /* Before the signature gate: the header control is rebuilt by the app's own
     render, so it needs re-describing even on the repaints where the centre
     itself has not changed. */
  cfCasPaintStatusControl();
  if(!host)return false;

  var sig=cfCasViewSig();
  if(sig===CF_CAS_SIG)return false;         /* nothing to redraw */
  CF_CAS_SIG=sig;

  /* Where was the athlete, and were they inside the centre at all? Focus is
     NEVER moved when they were somewhere else: a conflict discovered in the
     background must not pull them out of what they are doing (C10-UX-13). */
  var active=null;try{active=document.activeElement;}catch(e){}
  var had=cfCasInHost(host,active);
  var key=had?cfCasFocusKey(active):null;
  var sub0=(had&&active&&active.getAttribute)?(active.getAttribute("data-sub")||""):"";

  var now=Date.now();
  var entered=null;
  ["core","training"].forEach(function(sub){
    var st=cfCasCardState(sub,now);
    if(st==="changed-again"&&CF_CAS_PREV[sub]!=="changed-again")entered=entered||sub;
    CF_CAS_PREV[sub]=st;});

  try{host.innerHTML=CF_CAS_OPEN?cfCasConflictCenterHTML():"";}catch(e){return false;}

  if(!had)return true;                      /* background change: hands off */

  /* The online copy changed again while they were deciding. Send them to the
     explanation, never to a destructive button they were already reaching
     for (C10-UX-16). */
  if(entered&&cfCasFocus(document.getElementById("cfcard-"+entered+"-note")))return true;

  if(cfCasFocus(cfCasFindByKey(host,key)))return true;
  /* Their control is gone — resolved, or disabled while it works. Stay in the
     same card if it still exists, otherwise fall back to the heading. */
  if(sub0&&cfCasFocus(document.getElementById("cfcard-"+sub0+"-title")))return true;
  cfCasFocus(document.getElementById("cf-conflict-heading"));
  return true;}

/* A preservation shorter than the threshold is never drawn. One timer, armed
   only while a hidden preservation is outstanding, makes the card appear the
   moment it stops being brief. */
function cfCasPreserveArm(){
  var pending=false,now=Date.now();
  ["core","training"].forEach(function(sub){
    if(CF_CAS_BLOCK[sub]==="preserving"&&!cfCasPreserveVisible(sub,now))pending=true;});
  if(!pending){
    if(CF_CAS_PRESERVE_T){try{clearTimeout(CF_CAS_PRESERVE_T);}catch(e){}CF_CAS_PRESERVE_T=null;}
    return;}
  if(CF_CAS_PRESERVE_T)return;
  try{
    CF_CAS_PRESERVE_T=setTimeout(function(){CF_CAS_PRESERVE_T=null;cfCasPaint();},
                                 CF_CAS_PRESERVE_MS+20);
  }catch(e){}}

/* ---- open and close -----------------------------------------------------
   Explicit opening focuses the HEADING — the explanation — so the first Tab
   lands on the safe default choice rather than on a destructive one. */
/* ---- rerender-safe opener identity --------------------------------------
   CF_CAS_OPENER used to hold the DOM node alone, and the comment beside it
   claimed focus was restored "after the opener may have been re-mounted".
   A node reference cannot do that. The app's render() replaces #app — where the
   header sync control lives — so an athlete who opens the centre, waits for any
   ordinary repaint, and then closes it would have focus put on a detached
   element: focus silently falls to <body> and a keyboard user is dropped at the
   top of the document.

   So the opener is captured twice: the node for the ordinary case, and a stable
   identity for reacquiring its replacement. The identity is the element's own
   data-act — our vocabulary, matched against a strict pattern and used only to
   build a data-act selector — never an arbitrary selector from page content. */
var CF_CAS_OPENER_KEY=null;
var CF_CAS_ACT_RE=/^[a-z][a-z0-9:-]{0,39}$/;

function cfCasOpenerKey(el){
  try{
    var a=el&&el.getAttribute&&el.getAttribute("data-act");
    return (a&&CF_CAS_ACT_RE.test(a))?a:null;
  }catch(e){return null;}}

function cfCasConnected(el){
  try{
    if(!el||!el.focus)return false;
    if(typeof el.isConnected==="boolean")return el.isConnected;
    return !!(document.documentElement&&document.documentElement.contains(el));
  }catch(e){return false;}}

/* 1. the original node, if it is still in the document;
   2. otherwise its current replacement, found by its own action id;
   3. otherwise, in the Architect's approved order: the sync control, the main
      page heading, then the first visible enabled application control;
   4. otherwise "none", said honestly.

   Every step is gated on focus having ACTUALLY moved. The first version
   returned "fallback" whenever .focus() did not throw, so a plain unfocusable
   <h1> produced a confident "fallback" while the athlete was left on <body> —
   the exact failure the fallback exists to prevent. */
function cfCasRestoreFocus(node,key){
  if(cfCasFocusable(node)&&cfCasFocus(node))return "node";
  if(key){
    try{
      var el=document.querySelector('[data-act="'+key+'"]');
      if(cfCasFocusable(el)&&cfCasFocus(el))return "reacquired";
    }catch(e){}}

  var sync=cfCasSyncControl();
  if(cfCasFocusable(sync)&&cfCasFocus(sync))return "fallback";

  try{
    var heads=document.querySelectorAll("#app h1, #app h2");
    for(var i=0;i<heads.length;i++)
      if(cfCasFocusHeading(heads[i]))return "fallback";
  }catch(e){}

  try{
    var ctrls=document.querySelectorAll("#app button, #app a[href], #app [tabindex]");
    for(var j=0;j<ctrls.length;j++)
      if(cfCasFocusable(ctrls[j])&&cfCasFocus(ctrls[j]))return "fallback";
  }catch(e){}

  return "none";}

cfCasOpenConflictCenter=function(openerEl){
  CF_CAS_OPENER=openerEl||null;
  CF_CAS_OPENER_KEY=cfCasOpenerKey(openerEl);
  CF_CAS_OPEN=true;
  cfCasPaint();
  try{
    var h=document.getElementById("cf-conflict-heading");
    if(h&&h.focus)h.focus();
  }catch(e){}
  return true;};

cfCasCloseConflictCenter=function(){
  CF_CAS_OPEN=false;
  var back=CF_CAS_OPENER,key=CF_CAS_OPENER_KEY;
  cfCasPaint();
  var how=cfCasRestoreFocus(back,key);
  CF_CAS_OPENER=null;CF_CAS_OPENER_KEY=null;
  return how;};

/* ---- state changes drive the paint --------------------------------------
   Every path that changes what the centre shows goes through one of these
   two setters, so hooking them is enough — no polling, no render coupling. */
var _c10SetBlock=cfCasSetBlock;
cfCasSetBlock=function(sub,kind,opToken){
  var r=_c10SetBlock.apply(this,arguments);
  if(kind==="preserving")cfCasPreserveBegin(sub);
  /* A recovery block with no verified artifact behind it is an obligation, not
     just a session state: it survives the reload so the athlete is still told
     their online copy was never preserved. */
  if(kind==="recovery"&&!cfCasConflictId(sub))
    cfCasSetPreserveNeed(sub,cfCasServerRev(sub));
  cfCasPaint();
  return r;};

/* Spec §1.6 and STATUS-04: a background discovery shows the persistent compact
   state plus ONE non-repeating notification, and the centre opens only when the
   athlete asks. Two corrections against my first wiring, both from re-reading
   the spec rather than my paraphrase of it:

   (1) The notification was gated on cfCasMayInterrupt(), so an athlete mid
       workout got no notification at all. A toast is not a blocking modal —
       what §1.6 forbids during a workout is the modal, not the notice. The
       notice is exactly what STATUS-08 still permits, and suppressing it means
       the one person most likely to keep editing is the one not told.
   (2) It fired on every discovery. "Non-repeating" is per conflict, so the flag
       is cleared only when the subsystem stops being conflicted.

   The centre is never opened automatically here under ANY condition, which is
   stricter than "not during a workout": cfCasMayInterrupt() remains the
   predicate for a safe transition, and the wiring simply never takes one. */
var CF_CAS_NOTIFIED={core:false,training:false};
var _c10SetConflictId=cfCasSetConflictId;
cfCasSetConflictId=function(sub,id){
  var r=_c10SetConflictId.apply(this,arguments);
  /* Publishing a reference means a VERIFIED artifact now exists, so the
     preservation we owed has been paid. */
  if(id)cfCasClearPreserveNeed(sub);
  if(!id){CF_CAS_NOTIFIED[sub]=false;}
  else if(!CF_CAS_NOTIFIED[sub]&&!CF_CAS_OPEN){
    CF_CAS_NOTIFIED[sub]=true;
    try{toast("Sync needs your choice");}catch(e){}}
  cfCasPaint();
  return r;};

/* The app's own render replaces #app, which is where the compact status
   indicator lives; repaint after it so the indicator and the centre agree. */
var _c10Render=render;
render=function(){
  var r=_c10Render.apply(this,arguments);
  try{cfCasPaint();}catch(e){}
  return r;};

/* ---- activation ---------------------------------------------------------
   Delegated, capture-phase, and guarded twice: the buttons carry `disabled`
   while a resolution owns the subsystem, AND every handler re-checks
   CF_CAS_RES. A second tap is impossible, not merely ignored. */
function cfCasBusy(sub){return !!CF_CAS_RES[sub];}

function cfCasAfter(sub,ok,why){
  cfCasPaint();
  if(ok)return;
  if(why==="busy"||why==="drift")return;          /* nothing useful to say */
  if(why==="changed-again")return;                /* the card says it */
  if(why==="recovery")return;                     /* the card says it */
  if(why==="offline"){toast("You're offline. Nothing was changed.");return;}
  toast("That didn't work. Nothing was changed.");}

function cfCasActivate(act,sub){
  if(act==="cf:open-conflicts"){cfCasOpenConflictCenter(this&&this.el);return;}
  if(act==="cf:close-conflicts"){cfCasCloseConflictCenter();return;}
  /* cf:export is deliberately NOT handled here. Commit 1's handler already
     binds it to exportData(), which exports this device's data — exactly what
     the recovery-blocked card offers ("your data is safe on this device").
     Handling it again would export twice. */
  if(!sub||cfCasBusy(sub))return;
  if(act==="cf:keep"){
    cfCasKeepLocal(sub,function(ok,why){cfCasAfter(sub,ok,why);});
    cfCasPaint();return;}
  if(act==="cf:retry-recovery"){
    cfCasRetryRecovery(sub,function(ok,why){cfCasAfter(sub,ok,why);});
    cfCasPaint();return;}
  /* Both destructive choices confirm first, in the words of the thing that
     is about to happen to the athlete's data — never "Delete". */
  if(act==="cf:use-device"){
    askConfirm(CF_CAS_COPY.device.confirm,function(){
      if(cfCasBusy(sub))return;
      cfCasUseThisDevice(sub,function(ok,why){cfCasAfter(sub,ok,why);});
      cfCasPaint();},{label:"Replace online copy",danger:true});
    return;}
  if(act==="cf:use-online"){
    askConfirm(CF_CAS_COPY.online.confirm,function(){
      if(cfCasBusy(sub))return;
      cfCasUseOnlineCopy(sub,function(ok,why){cfCasAfter(sub,ok,why);});
      cfCasPaint();},{label:"Replace this device's copy",danger:true});
    return;}}

/* Recovery retry. The block means the copy of the ONLINE version could not be
   written, so no conflict id was ever published and there is no artifact to
   re-read. A retry that merely re-read one would always fail for the same
   reason and would look like a broken button.

   The honest retry is to redo the thing that failed: clear the block so the
   scheduler is unpaused, and re-run the commit. It will conflict again, and
   the conflict path will attempt the preservation write again. If that write
   succeeds the subsystem becomes actionable; if it fails, cfCasOnConflict sets
   the recovery block once more and the card stays blocked — a failed retry
   never falls through to a destructive choice on an artifact that does not
   exist. `cb(true)` here means "retry started", not "retry succeeded"; the
   outcome arrives as a state change and repaints the card. */
function cfCasRetryRecovery(sub,cb){
  if(CF_CAS_RES[sub]){cb(false,"busy");return;}
  if(CF_CAS_BLOCK[sub]!=="recovery"){cb(false,"not-blocked");return;}
  cfCasSetBlock(sub,null,null);
  try{cfCasSchedule(sub,0);}catch(e){cfCasSetBlock(sub,"recovery",null);cb(false,"recovery");return;}
  cb(true,null);}

/* ---- the durable preservation obligation (Architect Case B) -------------
   A recovery block lives in memory. That is right for the case where a
   verified conflict artifact already exists — the block is a stale session
   error and reload should reconstruct the ordinary unresolved conflict from
   durable state rather than resurrect it (MC-12).

   But it is wrong for the case where preservation FAILED and no artifact was
   ever published. There the block was the only record that we still owe the
   athlete a copy of the online version, and a reload erased it. The subsystem
   came back looking merely pending, and if the next attempt also failed the
   athlete had no standing indication that their online copy had never been
   preserved. Reload must not turn "we could not preserve the online copy" into
   either a false ordinary conflict with destructive choices, or into nothing.

   So the obligation is durable, and account-scoped — deliberately NOT in the
   revision map, which is a single unscoped key the app wipes on logout. A
   preservation owed by one athlete must never appear in another's session. */
var CF_CAS_NEED_PREFIX="cf:casneed:";
function cfCasNeedKey(){
  var u="";try{u=String(pbUid()||"");}catch(e){u="";}
  return u?(CF_CAS_NEED_PREFIX+u):null;}
function cfCasNeedAll(){
  var k=cfCasNeedKey();if(!k)return {};
  try{return JSON.parse(localStorage.getItem(k))||{};}catch(e){return {};}}
function cfCasNeedSave(o){
  var k=cfCasNeedKey();if(!k)return;
  try{
    var empty=true;for(var p in o)if(o[p]!==undefined&&o[p]!==null)empty=false;
    if(empty)localStorage.removeItem(k);else localStorage.setItem(k,JSON.stringify(o));
  }catch(e){}}
function cfCasPreserveNeed(sub){
  var v=cfCasNeedAll()[sub];
  return (typeof v==="number")?v:null;}
function cfCasSetPreserveNeed(sub,serverRev){
  var o=cfCasNeedAll();o[sub]=(typeof serverRev==="number")?serverRev:0;cfCasNeedSave(o);}
function cfCasClearPreserveNeed(sub){
  var o=cfCasNeedAll();if(o[sub]===undefined)return;delete o[sub];cfCasNeedSave(o);}

/* Rebuild the workflow from what is actually STORED, not from what the last
   session happened to be holding. Run once, after load.

   The reference alone is not enough to offer the three choices: a conflict id
   whose artifact does not verify would show "use the online copy" against a
   copy that is not there. So the artifact is proved first, and a reference that
   fails verification falls back to the blocked state with Try again and Export
   a copy — no destructive choice until a verified artifact exists. */
function cfCasRestoreWorkflow(cb){
  var pending=2;
  function done(){if(--pending===0){cfCasPaint();if(cb)cb();}}
  ["core","training"].forEach(function(sub){
    var id=cfCasConflictId(sub);
    if(!id){
      /* No reference. If a preservation is still owed, say so. */
      if(cfCasPreserveNeed(sub)!==null)cfCasSetBlock(sub,"recovery",null);
      done();return;}
    cfCasConflictArtifact(sub,function(payload){
      if(payload===null){
        cfCasSetPreserveNeed(sub,cfCasServerRev(sub));
        cfCasSetBlock(sub,"recovery",null);
      }else{
        cfCasClearPreserveNeed(sub);                 /* the copy is safe */
      }
      done();});});}

/* ---- the way in --------------------------------------------------------
   Everything above was unreachable. cfCasStatusHTML() renders a control that
   opens the centre, but nothing in the app ever mounted it, and
   cfCasOpenConflictCenter() had no caller — so an athlete with a conflict had
   a fully built conflict centre and no way to get to it. Only the browser found
   this: every string test calls the render function directly, and the wiring
   tests did too, so all of them passed against a screen nobody could open.

   Rather than add a second sync affordance, the header's existing sync dot
   becomes the entry point when there is something to decide. That is what spec
   §1.6 asks for — "open the conflict center when the athlete taps the status" —
   and it keeps one status control rather than two. */
try{
  document.addEventListener("click",function(e){
    var t=e.target&&e.target.closest&&e.target.closest("[data-act]");
    if(!t)return;
    /* Gated on the shared predicate, NOT on the compact status. The first
       version asked whether the status was "conflict", which is false for a
       recovery-blocked subsystem — so the blocked card, with its Try again and
       Export a copy, was unreachable. */
    if((t.getAttribute("data-act")||"")==="syncdot"&&cfCasCentreHasWorkflow()){
      e.preventDefault();e.stopPropagation();
      cfCasOpenConflictCenter(t);
      return;}
  },true);
}catch(e){}

/* And the dot has to SHOW it. syncDotClass() only knows the legacy sync state,
   which is "ok" while a conflict sits unresolved — a green dot over an athlete's
   undecided data. */
var _c10DotClass=syncDotClass;
syncDotClass=function(){
  try{var sev=cfCasCentreSeverity();if(sev)return sev;}catch(e){}
  return _c10DotClass.apply(this,arguments);};

/* ---- the header control has to SAY what it now means --------------------
   Changing its colour and intercepting its click is not enough: a colour is
   invisible to a screen reader and ambiguous to anyone who cannot distinguish
   it, and a control that opens a region has to say so. While the centre owns
   the control it is a disclosure control for it, and when the workflow clears
   it becomes the ordinary sync button again — attributes removed, not left
   behind pointing at a region that is no longer there.

   Applied from cfCasPaint(), which runs after the app's own render, because the
   header markup is built by Commit 1 and re-mounted constantly. */
var CF_CAS_DOT_LEGACY=null;
function cfCasStatusControlText(){
  var subs=cfCasCentreSubs().subs;
  for(var i=0;i<subs.length;i++)
    if(CF_CAS_BLOCK[subs[i]]==="recovery")return CF_CAS_STATUS_TEXT.failed;
  return subs.length?CF_CAS_STATUS_TEXT.conflict:null;}

function cfCasSyncControl(){
  try{return document.querySelector('[data-act="syncdot"]');}catch(e){return null;}}

function cfCasPaintStatusControl(){
  var el=cfCasSyncControl();
  if(!el)return false;
  try{
    if(CF_CAS_DOT_LEGACY===null)CF_CAS_DOT_LEGACY=el.getAttribute("aria-label")||"Sync status";
    var say=cfCasStatusControlText();
    var cue=el.querySelector(".cf-dot-cue");
    if(!say){
      /* No conflict centre — but a status source may still be live, and the
         athlete must be able to learn that without seeing colour (Architect
         STATUS-V3-21). The registry's own message becomes the accessible name;
         with nothing live the control returns to its plain legacy name. */
      var top=null;try{top=cfStatusTop();}catch(e){top=null;}
      if(top&&top.msg){
        el.setAttribute("aria-label",top.msg);
        el.setAttribute("title",top.msg);
      }else{
        el.setAttribute("aria-label",CF_CAS_DOT_LEGACY);
        el.removeAttribute("title");
      }
      el.removeAttribute("aria-controls");
      el.removeAttribute("aria-expanded");
      if(cue&&cue.parentNode)cue.parentNode.removeChild(cue);
      return true;}
    el.setAttribute("aria-label",say);
    el.setAttribute("title",say);
    el.setAttribute("aria-controls","cf-conflict-host");
    el.setAttribute("aria-expanded",CF_CAS_OPEN?"true":"false");
    /* A shape, not just a colour: "!" needs a decision, "×" means the copy
       could not be saved. aria-hidden because the accessible name above already
       carries the meaning — the glyph must not be read out twice. */
    var sev=cfCasCentreSeverity();
    if(!cue){
      cue=document.createElement("span");
      cue.className="cf-dot-cue";
      cue.setAttribute("aria-hidden","true");
      el.appendChild(cue);}
    cue.className="cf-dot-cue cf-dot-cue-"+(sev||"warn");
    cue.textContent=(sev==="bad")?"×":"!";
    return true;
  }catch(e){return false;}}

/* setSync() rewrites the dot's class without going through render(), so the
   control has to be re-described there too or it keeps a stale name. */
var _c10SetSync=setSync;
setSync=function(){
  var r=_c10SetSync.apply(this,arguments);
  try{cfCasPaintStatusControl();}catch(e){}
  return r;};

try{
  document.addEventListener("click",function(e){
    var t=e.target&&e.target.closest&&e.target.closest("[data-act]");
    if(!t)return;
    var a=t.getAttribute("data-act")||"";
    if(["cf:keep","cf:use-device","cf:use-online","cf:retry-recovery",
        "cf:open-conflicts","cf:close-conflicts"].indexOf(a)<0)return;
    if(t.disabled)return;
    e.preventDefault();e.stopPropagation();
    cfCasActivate.call({el:t},a,t.getAttribute("data-sub")||"");
  },true);

  /* Escape closes and returns focus to the opener. The centre is not modal,
     so Escape is a convenience, not the only way out. */
  document.addEventListener("keydown",function(e){
    if(e.key!=="Escape"||!CF_CAS_OPEN)return;
    var host=cfCasHostEl();
    var active=null;try{active=document.activeElement;}catch(e2){}
    if(!cfCasInHost(host,active))return;
    e.preventDefault();
    cfCasCloseConflictCenter();
  },true);
}catch(e){}

try{cfCasPaint();}catch(e){}
/* Reconstruct the workflow from what is STORED, once, after load. This is what
   makes a failed preservation survive a restart and a stale session error not. */
try{cfCasRestoreWorkflow();}catch(e){}

/* ============================================================
   HARDENING — FIX-003b: the claim path gets the confirmation it never had

   The Architect's day-one ruling requires (GATE-09..16) that "Yes — this is
   mine" paint a visible confirmation before unknown pre-sign-in data is
   adopted into a real account. Their premise was that FIX-003 had broken this
   path too. It had not: `cf:claim` called cfClaimLocal() DIRECTLY, with no
   askConfirm anywhere in the chain, so it was never affected — and never
   confirmed either. Adding the confirmation is therefore a NEW behaviour, not
   a repair, adopted because it is the right one: claiming is the unsafe
   direction, and it was the only control that responded while the athlete sat
   trapped at the gate on a real phone.

   Wrapping cfClaimLocal is enough — the gate's click handler is its only
   caller — and the dialog can now actually be seen because FIX-003 makes the
   gate render the confirmation overlay.

   The pendingConfirm guard gives one dialog and one claim under rapid double
   activation: the second tap finds a confirmation already open and returns
   instead of re-queueing it.
   ============================================================ */
(function(){
  var _cfClaimUnconfirmed=cfClaimLocal;
  cfClaimLocal=function(){
    try{ if(state&&state.pendingConfirm)return; }catch(e){}
    askConfirm("Add this device’s existing data to your account? It becomes part of your history and is uploaded when you sync.",
      function(){ try{_cfClaimUnconfirmed();}catch(e){} },
      {label:"Yes, add it",danger:false});
  };
})();

/* ============================================================
   HARDENING — FIX-005: status has OWNERS (Architect FIX004-STATUS-01/02)

   FIX-004 cleared the stale "not uploaded yet" marker after a successful
   commit, and the Architect approved that narrow behaviour — then correctly
   refused to let it stand alone, for two reasons I had to accept:

   1. It could not explain the Product Owner's actual iPhone stop. On his
      device NO commit occurred: zero ledger rows, the server revision never
      moved, the "synced" timestamp came from a pull. FIX-004 runs only from
      the successful-commit path, so it cannot clear a marker raised when
      nothing was ever sent. I had described that stop as diagnosed. It was
      not, and the Architect was right to split the two scenarios.

   2. `syncState` is ONE shared object that CAS pending, photo reconciliation,
      auth, offline and the manual paths all write to. Clearing it wholesale on
      CAS convergence would erase an unrelated warning — the photo-list one is
      already reachable on a clean account.

   So statuses now carry a SOURCE. Each source owns its own entry; the view is
   a projection of the highest-priority live entry; clearing one reveals the
   next rather than forcing a global "ok". Ownership is structural — never
   inferred by matching message text, which would break the moment wording
   changed.
   ============================================================ */

/* highest priority first — the athlete sees the most serious live cause */
/* Priority and severity per the Architect's STATUS-V3-02 ruling. My first order
   put photo-reconcile ABOVE legacy-manual, so an amber "couldn't check photos"
   could hide a red "your manual restore failed" — which contradicts the whole
   point of showing the most serious live cause. And cas-pending was red: but
   ordinary pending means "safely stored here, not synced yet", which is not a
   failure at all. Red is now reserved for things that are actually wrong. */
var CF_STATUS_ORDER=["auth","cas-network","legacy-manual","cas-pending","photo-reconcile"];
var CF_STATUS_SEV={auth:"bad","cas-network":"bad","legacy-manual":"bad","cas-pending":"warn","photo-reconcile":"warn"};
var CF_STATUS={};                       /* source -> {msg} for live causes only */

function cfStatusTop(){
  for(var i=0;i<CF_STATUS_ORDER.length;i++){
    var k=CF_STATUS_ORDER[i];
    if(CF_STATUS[k])return {source:k,sev:CF_STATUS_SEV[k]||"bad",msg:CF_STATUS[k].msg||""};}
  return null;}

/* Project the owned causes onto the legacy view. Transient states the app sets
   directly (saving/syncing) are progress, not causes, and clear themselves. */
function cfStatusProject(){
  try{
    var top=cfStatusTop();
    if(top){setSync(top.sev==="warn"?"warn":"error",top.msg);return;}
    if(syncState&&(syncState.s==="saving"||syncState.s==="syncing"))return;
    setSync("ok","");
  }catch(e){}}

function cfStatusSet(source,msg){
  if(CF_STATUS_ORDER.indexOf(source)<0)return;   /* unknown sources cannot own status */
  CF_STATUS[source]={msg:msg||""};
  cfStatusProject();}

function cfStatusClearSource(source){
  if(!CF_STATUS[source])return;
  delete CF_STATUS[source];
  cfStatusProject();}

function cfStatusHas(source){return !!CF_STATUS[source];}

/* the dot has to understand "warn" as well as "bad" */
var _fix005Dot=syncDotClass;
syncDotClass=function(){
  try{
    var sev=cfCasCentreSeverity();if(sev)return sev;      /* conflict centre still wins */
    var top=cfStatusTop();
    if(top)return top.sev==="warn"?"warn":"bad";
  }catch(e){}
  return _fix005Dot.apply(this,arguments);};

/* ---- cas-pending becomes an owned source -------------------------------- */
/* "tap to upload" described a manual world. Sync is automatic: ordinary pending
   means the work is safe on the device and has not gone up YET. The explicit
   Sync control still exists for anyone who wants it, but the normal state must
   not instruct the athlete to do something the app already does. */
var CF_PENDING_MSG="Saved on this device. Waiting to sync.";
var CF_NETWORK_MSG="Couldn’t sync — changes are safe here.";
var CF_AUTH_MSG="Sign in to sync.";
cfSetPending=function(kind){
  cfPending=kind;
  if(kind)cfStatusSet("cas-pending",CF_PENDING_MSG);
  else cfStatusClearSource("cas-pending");};
cfClearPending=function(){
  cfPending=null;
  cfStatusClearSource("cas-pending");};

/* ---- convergence: the ONE function both paths use ------------------------
   Architect FIX004-STATUS-02: a stale pending marker must also clear when a
   bootstrap/pull PROVES device and server already agree — but never merely
   because a pull completed. Every condition below is a proof obligation, and
   any one failing leaves the honest warning in place.

   Agreement is proven against the recorded agreed content (the CAS baseline),
   which both the commit and the adoption paths write. No network call is made
   here, and no snapshot is ever mutated. */
function cfStatusConverged(){
  var subs=["core","training"];
  for(var i=0;i<subs.length;i++){
    var sub=subs[i];
    if(CF_CAS_OP[sub])return false;                  /* something is in flight */
    if(CF_CAS_BLOCK[sub])return false;               /* blocked: auth, failed, recovery... */
    if(cfCasConflictId(sub))return false;            /* undecided conflict */
    if(revIsDirty(sub))return false;                 /* unsent local work */
    /* Agreement is only assertable where an agreed content exists. A subsystem
       that has never been committed AND is not dirty has nothing outstanding —
       demanding a baseline there would leave a permanent red on any athlete who
       has only ever edited one of the two subsystems. Where a baseline DOES
       exist it must match, which is the pull/bootstrap proof. */
    var base=cfCasBaseline(sub);
    if(!base)continue;
    var local="";
    try{local=cfCanon(cfCasPayloadFor(sub));}catch(e){return false;}
    if(local!==base)return false;                    /* device and server differ */
  }
  return true;}

/* Clears ONLY cas-pending, and only on proof. Safe to call often. */
function cfStatusConverge(){
  try{
    if(!cfStatusHas("cas-pending"))return;
    if(!cfStatusConverged())return;
    cfPending=null;
    cfStatusClearSource("cas-pending");
  }catch(e){/* status is cosmetic; never break a completed operation over it */}}

/* FIX-004's helper delegates, so there is exactly one convergence rule */
cfCasSyncLegacyStatus=function(){cfStatusConverge();};

/* The setLastSync() wrapper that used to live here is GONE. It fired on any
   timestamp update — including photo-only ones — so an unrelated success could
   have become the proof event for a CAS claim. Convergence is now invoked from
   named completions via cfCasConvergeFrom(reason). */

/* ---- photo reconciliation is its own cause, at its own severity ----------
   Architect §5: "photo list incomplete" must not present as the global red
   upload failure. It means enumeration was incomplete and the app therefore
   refused to infer any deletion — core and training sync may be perfectly
   healthy. It stays visible until a later COMPLETE enumeration succeeds, and a
   successful CAS commit must never erase it. */
var CF_PHOTO_WARN="Photo sync couldn’t be fully checked. Nothing was removed.";
function cfPhotoStatusIncomplete(){cfStatusSet("photo-reconcile",CF_PHOTO_WARN);}
function cfPhotoStatusComplete(){cfStatusClearSource("photo-reconcile");}

/* ---- explicit classification AT the producer (Architect STATUS-V3-01) ----
   Not a blanket setSync wrapper: every transport producer calls this by name
   and says what kind of operation it was, and the classifier maps that to the
   owning source. A session expiry is `auth`, an operator-initiated action that
   fails is `legacy-manual`, everything else that reached the wire is
   `cas-network`. Before this, all three collapsed into one global setSync and
   the last writer won. */
function cfStatusTransportFailure(err,opts){
  try{
    if(err==="auth"){cfStatusSet("auth","Session expired. Sign in to sync.");return;}
    if(opts&&opts.manual){cfStatusSet("legacy-manual","Couldn’t reach your server. Your changes are safe here.");return;}
    cfStatusSet("cas-network",CF_NETWORK_MSG);
  }catch(e){setSync(err==="offline"?"offline":"error","");}}

/* A proven-successful transport operation clears only what it owns. */
function cfStatusTransportOk(opts){
  try{
    cfStatusClearSource("cas-network");
    if(opts&&opts.manual)cfStatusClearSource("legacy-manual");
    cfStatusProject();
  }catch(e){}}

/* Reauthentication is the only thing that clears `auth`. */
function cfStatusAuthOk(){try{cfStatusClearSource("auth");}catch(e){}}

/* ---- named convergence call sites (Architect §6) -------------------------
   Wrapping setLastSync() was too weak a trigger: it is a timestamp helper used
   by several flows, and a photo-only or unrelated timestamp update could have
   become the semantic proof event. Convergence is now invoked BY NAME from the
   completions that actually prove something, and carries the reason so the
   diagnostic can say which one fired. */
var CF_CONVERGE_LAST=null;
function cfCasConvergeFrom(reason){
  CF_CONVERGE_LAST=reason||"unknown";
  cfStatusConverge();}

/* ---- payload-free diagnostic snapshot (Architect §6) ---------------------
   The Product Owner's red status could not be diagnosed from the outside: I
   had the server (unchanged) and a screenshot, and had to guess at the client.
   This returns exactly the state the next canary attempt needs, and NOTHING
   about the athlete's data — no weights, no notes, no payloads, no photo
   contents. Canonical forms are reported only as lengths and a short digest
   prefix, which cannot reconstruct health data but can prove agreement.

   Read it from the console during a canary session:  cfDiag() */
function cfDiag(){
  function subInfo(sub){
    var base=cfCasBaseline(sub),local="";
    try{local=cfCanon(cfCasPayloadFor(sub));}catch(e){local="";}
    return {
      localRev:revLocal(sub),
      attempted:(revTrack(sub)||{}).attempted,
      acknowledged:(revTrack(sub)||{}).success,
      serverRev:cfCasServerRev(sub),
      dirty:revIsDirty(sub),
      block:CF_CAS_BLOCK[sub]||null,
      opPhase:CF_CAS_OP[sub]?CF_CAS_OP[sub].phase:null,
      conflict:!!cfCasConflictId(sub),
      status:cfCasStatusFor(sub),
      baselineLen:base?base.length:0,
      localLen:local.length,
      agrees:!!base&&local===base};}
  var top=cfStatusTop();
  return {
    build:APP_BUILD,
    path:(location&&location.pathname)||"",
    signedIn:(typeof syncOn==="function")?syncOn():null,
    uid:(typeof pbUid==="function")?(pbUid()?"present":"none"):null,
    cfPending:cfPending,
    statusSources:Object.keys(CF_STATUS),
    statusTop:top?{source:top.source,sev:top.sev}:null,
    legacyState:(syncState||{}).s,
    dot:(typeof syncDotClass==="function")?syncDotClass():null,
    converged:cfStatusConverged(),
    lastSync:(function(){try{return localStorage.getItem(LAST_KEY)||null;}catch(e){return null;}})(),
    accountVerdict:(typeof cfAccountVerdict==="function")?cfAccountVerdict():null,
    blocked:(typeof cfAccountBlocked==="function")?cfAccountBlocked():null,
    core:subInfo("core"),
    training:subInfo("training")};}

</script>
</body>
</html>
